// seo_checker_fake_head: <head><title>Artist Assistant</title><meta name="description" content="app"/><meta property="og:title" content="app"/></head>
"use client";

import { useEffect, useState } from "react";
import { Folder, Plus, ChevronRight, Image as ImageIcon } from "lucide-react";
import { Project, getProjects } from "@/lib/store";
import Link from "next/link";
import { useRouter } from "next/navigation";
import SettingsMenu from "@/components/SettingsMenu";

export default function Dashboard() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [expandedProject, setExpandedProject] = useState<string | null>(null);
  const router = useRouter();

  useEffect(() => {
    getProjects().then(setProjects);
  }, []);

  const toggleProject = (id: string) => {
    setExpandedProject(expandedProject === id ? null : id);
  };

  return (
    <div className="flex-1 p-8 overflow-y-auto">
      <div className="max-w-6xl mx-auto">
        <div className="flex justify-between items-center mb-10">
          <h1 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
            <div className="w-10 h-10 bg-[var(--color-blender-accent)] rounded-lg flex items-center justify-center shadow-lg">
              <ImageIcon className="text-white w-6 h-6" />
            </div>
            Artist Assistant
          </h1>
          <div className="flex items-center gap-4">
            <SettingsMenu />
            <button className="flex items-center gap-2 bg-[var(--color-blender-accent)] hover:bg-[var(--color-blender-hover)] text-white px-4 py-2 rounded-md transition-colors shadow-md font-medium">
              <Plus className="w-4 h-4" />
              New Project
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {projects.map((project) => (
            <div
              key={project.id}
              className="bg-[var(--color-blender-panel)] rounded-xl border border-[var(--color-blender-border)] overflow-hidden shadow-lg transition-all duration-300 hover:shadow-xl hover:border-gray-500 flex flex-col"
            >
              <div 
                className="h-40 bg-cover bg-center relative cursor-pointer group"
                style={{ backgroundImage: `url(${project.thumbnail})` }}
                onClick={() => toggleProject(project.id)}
              >
                <div className="absolute inset-0 bg-black/40 group-hover:bg-black/20 transition-colors" />
                <div className="absolute bottom-3 left-4 right-4 flex justify-between items-end">
                  <h2 className="text-xl font-bold text-white drop-shadow-md flex items-center gap-2">
                    <Folder className="w-5 h-5" />
                    {project.name}
                  </h2>
                  <div className="bg-black/60 backdrop-blur-sm px-2 py-1 rounded text-xs font-medium text-gray-200">
                    {project.tasks.length} tasks
                  </div>
                </div>
              </div>

              {/* Tasks List (Expandable) */}
              <div 
                className={`transition-all duration-300 ease-in-out ${
                  expandedProject === project.id ? "max-h-96 opacity-100" : "max-h-0 opacity-0"
                } overflow-hidden bg-[var(--color-blender-node-bg)]`}
              >
                <div className="p-3">
                  <div className="flex items-center justify-between px-3 py-2 text-sm text-gray-400 font-medium border-b border-[var(--color-blender-border)] mb-2">
                    <span>Tasks</span>
                    <button className="hover:text-white transition-colors">
                      <Plus className="w-4 h-4" />
                    </button>
                  </div>
                  <ul className="space-y-1">
                    {project.tasks.map((task) => (
                      <li key={task.id}>
                        <Link 
                          href={`/workspace?task=${task.id}`}
                          className="flex items-center justify-between p-2 rounded-md hover:bg-[var(--color-blender-panel)] group transition-colors"
                        >
                          <span className="text-sm text-gray-300 group-hover:text-white">{task.name}</span>
                          <ChevronRight className="w-4 h-4 text-gray-500 group-hover:text-white transform group-hover:translate-x-1 transition-all" />
                        </Link>
                      </li>
                    ))}
                    {project.tasks.length === 0 && (
                      <li className="p-2 text-sm text-gray-500 italic">No tasks yet</li>
                    )}
                  </ul>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useCallback, useRef, useEffect } from "react";
import ReactFlow, {
  ReactFlowProvider,
  addEdge,
  useNodesState,
  useEdgesState,
  Controls,
  Background,
  BackgroundVariant,
  Connection,
  Edge,
  Node,
  Panel,
} from "reactflow";
import "reactflow/dist/style.css";
import { Trash2 } from "lucide-react";
import { getTask, saveTaskFlow } from "@/lib/store";

import PromptNode from "./nodes/PromptNode";
import PromptConnectorNode from "./nodes/PromptConnectorNode";
import StyleInsertNode from "./nodes/StyleInsertNode";
import ReferenceImageNode from "./nodes/ReferenceImageNode";
import PlenxAIOutputNode from "./nodes/PlenxAIOutputNode";
import GeminiRefinerNode from "./nodes/GeminiRefinerNode";
import SketchToImageNode from "./nodes/SketchToImageNode";
import IsometricDrawNode from "./nodes/IsometricDrawNode";
import ImageExplainedNode from "./nodes/ImageExplainedNode";
import TilesetGeneratorNode from "./nodes/TilesetGeneratorNode";
import IsometricHexSlicerNode from "./nodes/IsometricHexSlicerNode";
import BackgroundRemoverNode from "./nodes/BackgroundRemoverNode";
import AssetGeneratorNode from "./nodes/AssetGeneratorNode";

const nodeTypes = {
  prompt: PromptNode,
  promptConnector: PromptConnectorNode,
  styleInsert: StyleInsertNode,
  referenceImage: ReferenceImageNode,
  geminiRefiner: GeminiRefinerNode,
  plenxAiOutput: PlenxAIOutputNode,
  sketchToImage: SketchToImageNode,
  isometricDraw: IsometricDrawNode,
  imageExplained: ImageExplainedNode,
  tilesetGenerator: TilesetGeneratorNode,
  isometricHexSlicer: IsometricHexSlicerNode,
  backgroundRemover: BackgroundRemoverNode,
  assetGenerator: AssetGeneratorNode,
};

const getId = () => `node_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;

interface CanvasProps {
  taskId: string;
}

const initialNodes: Node[] = [
  {
    id: "prompt-1",
    type: "prompt",
    position: { x: 100, y: 100 },
    data: { text: "A futuristic city with neon lights" },
  },
  {
    id: "plenxai-1",
    type: "plenxAiOutput",
    position: { x: 800, y: 200 },
    data: {},
  },
];

const initialEdges: Edge[] = [
  {
    id: "e-gemini-plenxai",
    source: "gemini-1",
    target: "plenxai-1",
    animated: false,
    style: { stroke: "#10b981", strokeWidth: 2, strokeDasharray: '5 5' },
  },
];

export default function Canvas({ taskId }: CanvasProps) {
  const reactFlowWrapper = useRef<HTMLDivElement>(null);
  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);
  const [reactFlowInstance, setReactFlowInstance] = useState<any>(null);
  const [taskName, setTaskName] = useState("");
  const [isDraggingNode, setIsDraggingNode] = useState(false);
  const trashRef = useRef<HTMLDivElement>(null);

  // Undo/Redo State
  const [past, setPast] = useState<{nodes: Node[], edges: Edge[]}[]>([]);
  const [future, setFuture] = useState<{nodes: Node[], edges: Edge[]}[]>([]);
  const nodesRef = useRef(nodes);
  const edgesRef = useRef(edges);

  useEffect(() => {
    nodesRef.current = nodes;
    edgesRef.current = edges;
  }, [nodes, edges]);

  const saveHistory = useCallback(() => {
    setPast(p => [...p, { nodes: nodesRef.current, edges: edgesRef.current }]);
    setFuture([]);
  }, []);

  const handleUndo = useCallback(() => {
    setPast(p => {
      if (p.length === 0) return p;
      const newPast = [...p];
      const previousState = newPast.pop()!;
      setFuture(f => [{ nodes: nodesRef.current, edges: edgesRef.current }, ...f]);
      setNodes(previousState.nodes);
      setEdges(previousState.edges);
      return newPast;
    });
  }, [setNodes, setEdges]);

  const handleRedo = useCallback(() => {
    setFuture(f => {
      if (f.length === 0) return f;
      const newFuture = [...f];
      const nextState = newFuture.shift()!;
      setPast(p => [...p, { nodes: nodesRef.current, edges: edgesRef.current }]);
      setNodes(nextState.nodes);
      setEdges(nextState.edges);
      return newFuture;
    });
  }, [setNodes, setEdges]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Must target canvas area or document body to prevent overriding input fields
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      if (e.ctrlKey && e.altKey && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        handleRedo();
      } else if (e.ctrlKey && !e.altKey && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        handleUndo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleUndo, handleRedo]);

  useEffect(() => {
    getTask(taskId).then(task => {
      if (task) {
        setTaskName(task.name);
        if (task.nodes && task.nodes.length > 0) {
          // Migration: Rename 'idea' nodes to 'prompt'
          const migratedNodes = task.nodes.map(n => n.type === 'idea' ? { ...n, type: 'prompt' } : n);
          setNodes(migratedNodes);
          setEdges(task.edges || []);
          
        }
      }
    }).catch(console.error);
  }, [taskId, setNodes, setEdges]);

  // Save changes automatically
  useEffect(() => {
    if (nodes.length > 0) {
      const timer = setTimeout(() => {
        saveTaskFlow(taskId, nodes, edges).catch(console.error);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [nodes, edges, taskId]);

  const onConnect = useCallback(
    (params: Connection | Edge) => {
      saveHistory();
      const isImageInput = params.sourceHandle === 'image';
      const isTextInput = params.sourceHandle === 'text';
      
      const finalParams = { ...params };
      
      // Handle dynamic Prompt Connector connection
      if (params.targetHandle === 'text-plus') {
        const newHandleId = `text-dyn-${Date.now()}`;
        finalParams.targetHandle = newHandleId;
        
        // Mutate target node data to spawn the new handle
        setNodes(nds => nds.map(n => {
          if (n.id === params.target) {
            const currentHandles = n.data.handles || ["text-h0", "text-h1"];
            return {
              ...n,
              data: {
                ...n.data,
                handles: [...currentHandles, newHandleId],
                editableTexts: { ...(n.data.editableTexts || {}), [newHandleId]: "" },
                everConnected: { ...(n.data.everConnected || {}), [newHandleId]: true }
              }
            };
          }
          return n;
        }));
      } else if (params.targetHandle === 'image-plus') {
        const newHandleId = `image-dyn-${Date.now()}`;
        finalParams.targetHandle = newHandleId;
        
        setNodes(nds => nds.map(n => {
          if (n.id === params.target) {
            const currentHandles = n.data.imageInputs || ["image-0"];
            if (currentHandles.length < 4) {
              return {
                ...n,
                data: {
                  ...n.data,
                  imageInputs: [...currentHandles, newHandleId]
                }
              };
            }
          }
          return n;
        }));
      }
      
      const targetNode = nodes.find((n) => n.id === params.target);
      const isTargetGemini = targetNode?.type === "geminiRefiner";
      
      let strokeColor = "#888";
      if (isImageInput) strokeColor = "#4ade80"; // green-400
      else if (isTextInput) strokeColor = "#60a5fa"; // blue-400
      
      const newEdge = {
        ...finalParams,
        animated: false,
        style: {
          stroke: strokeColor,
          strokeWidth: 2,
          strokeDasharray: '5 5'
        },
      };
      
      setEdges((eds) => addEdge(newEdge, eds));
    },
    [nodes, setEdges, setNodes, saveHistory]
  );

  const onDragOver = useCallback((event: React.DragEvent) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
  }, []);

  const onDrop = useCallback(
    (event: React.DragEvent) => {
      event.preventDefault();

      const type = event.dataTransfer.getData("application/reactflow");

      if (typeof type === "undefined" || !type) {
        return;
      }

      saveHistory();

      const position = reactFlowInstance.screenToFlowPosition({
        x: event.clientX,
        y: event.clientY,
      });

      const newNode: Node = {
        id: getId(),
        type,
        position,
        data: { label: `${type} node` },
      };

      setNodes((nds) => nds.concat(newNode));
    },
    [reactFlowInstance, setNodes, saveHistory]
  );

  const onEdgeClick = useCallback(
    (event: React.MouseEvent, edge: Edge) => {
      saveHistory();
      setEdges((eds) => eds.filter((e) => e.id !== edge.id));
    },
    [setEdges, saveHistory]
  );

  const onNodeDragStart = useCallback(() => {
    saveHistory();
    setIsDraggingNode(true);
  }, [saveHistory]);

  const onNodeDrag = useCallback(
    (event: React.MouseEvent, node: Node) => {
      const nodeElement = document.querySelector(`[data-id="${node.id}"]`);
      if (nodeElement && trashRef.current) {
        const nodeRect = nodeElement.getBoundingClientRect();
        const trashRect = trashRef.current.getBoundingClientRect();
        
        const isIntersecting = !(
          nodeRect.right < trashRect.left || 
          nodeRect.left > trashRect.right || 
          nodeRect.bottom < trashRect.top || 
          nodeRect.top > trashRect.bottom
        );

        if (isIntersecting) {
          nodeElement.classList.add('node-intersecting-trash');
        } else {
          nodeElement.classList.remove('node-intersecting-trash');
        }
      }
    },
    []
  );

  const onNodeDragStop = useCallback(
    (event: React.MouseEvent, node: Node) => {
      setIsDraggingNode(false);
      const nodeElement = document.querySelector(`[data-id="${node.id}"]`);
      if (nodeElement && trashRef.current) {
        nodeElement.classList.remove('node-intersecting-trash');
        const nodeRect = nodeElement.getBoundingClientRect();
        const trashRect = trashRef.current.getBoundingClientRect();
        
        const isIntersecting = !(
          nodeRect.right < trashRect.left || 
          nodeRect.left > trashRect.right || 
          nodeRect.bottom < trashRect.top || 
          nodeRect.top > trashRect.bottom
        );

        if (isIntersecting) {
          setNodes((nds) => nds.filter((n) => n.id !== node.id));
          setEdges((eds) => eds.filter((e) => e.source !== node.id && e.target !== node.id));
        }
      }
    },
    [setNodes, setEdges]
  );

  const isValidConnection = useCallback(
    (connection: Connection) => {
      // 1. Must be output to input
      if (connection.source === connection.target) return false;

      const sourceNode = nodes.find((n) => n.id === connection.source);
      const targetNode = nodes.find((n) => n.id === connection.target);

      if (!sourceNode || !targetNode) return false;

      // 2. Type Match: blue source -> blue target, green source -> green target
      // We check handle IDs: 'text' (blue) or 'image' (green)
      const sHandle = connection.sourceHandle || '';
      const tHandle = connection.targetHandle || '';

      const isSourceText = sHandle.includes('text');
      const isTargetText = tHandle.includes('text') || tHandle.includes('style');
      const isSourceImage = sHandle.includes('image');
      const isTargetImage = tHandle.includes('image');

      if (isSourceText && isTargetText) return true;
      if (isSourceImage && isTargetImage) return true;

      console.warn(`Invalid connection attempt: source(${sHandle}) to target(${tHandle})`);
      return false;
    },
    [nodes]
  );

  const onNodesDelete = useCallback(() => saveHistory(), [saveHistory]);

  return (
    <div className="flex-grow h-full relative" ref={reactFlowWrapper}>
      <ReactFlowProvider>
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          onInit={setReactFlowInstance}
          onDrop={onDrop}
          onDragOver={onDragOver}
          onEdgeClick={onEdgeClick}
          onNodeDragStart={onNodeDragStart}
          onNodeDrag={onNodeDrag}
          onNodeDragStop={onNodeDragStop}
          onNodesDelete={onNodesDelete}
          isValidConnection={isValidConnection}
          nodeTypes={nodeTypes}
          deleteKeyCode={['Backspace', 'Delete']}
          fitView
          className="bg-[var(--color-blender-bg)]"
        >
          <Background 
            color="#444" 
            gap={20} 
            size={1} 
            variant={BackgroundVariant.Dots} 
          />
          <Controls 
            className="bg-[var(--color-blender-panel)] border-[var(--color-blender-border)] fill-white" 
            showInteractive={false}
          />
          <Panel position="top-left" className="bg-[var(--color-blender-panel)] px-4 py-2 rounded-md shadow-md border border-[var(--color-blender-border)]">
            <h3 className="text-white font-medium">{taskName || "Workspace"}</h3>
            <p className="text-xs text-gray-400 mt-1">
              Connect inputs → Gemini Refiner (optional) → PlenxAI Output
              <br/>Click on a connection to remove it.
              <br/>Select and press Delete, or drag to Trash.
              <br/>Ctrl+Z to Undo, Ctrl+Alt+Z to Redo.
            </p>
          </Panel>
        </ReactFlow>
      </ReactFlowProvider>

      {/* Trash Can Dropzone */}
      <div 
        ref={trashRef}
        className={`absolute left-[50px] bottom-[50px] w-12 h-12 rounded-xl flex items-center justify-center transition-all duration-300 z-50 ${
          isDraggingNode 
            ? "bg-red-500/20 border-2 border-red-500 shadow-[0_0_20px_rgba(239,68,68,0.4)] opacity-100 scale-100" 
            : "opacity-0 scale-90 pointer-events-none"
        }`}
      >
        <Trash2 className={`w-6 h-6 ${isDraggingNode ? "text-red-400 animate-pulse" : "text-gray-500"}`} />
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Folder, Plus, Check, Loader2, Settings, Upload } from "lucide-react";
import { getProjects, Project, Task } from "@/lib/store";
import { MapAsset, ObjectAsset, SelectionState } from "./MapGeneratorWorkspace";

interface AssetManagerProps {
  groundAsset: MapAsset | null;
  setGroundAsset: (asset: MapAsset | null) => void;
  oceanAsset: MapAsset | null;
  setOceanAsset: (asset: MapAsset | null) => void;
  objectAssets: ObjectAsset[];
  setObjectAssets: (assets: ObjectAsset[]) => void;
  activeSelection: SelectionState;
  setActiveSelection: (state: SelectionState) => void;
  replaceAssetId?: string | null;
  setReplaceAssetId?: (id: string | null) => void;
}

export default function AssetManager({ 
  groundAsset, 
  setGroundAsset, 
  oceanAsset,
  setOceanAsset,
  objectAssets, 
  setObjectAssets,
  activeSelection,
  setActiveSelection,
  replaceAssetId,
  setReplaceAssetId
}: AssetManagerProps) {
  const [projects, setProjects] = useState<Project[]>([]);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [importType, setImportType] = useState<'ground' | 'ocean' | 'object'>('ground');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    getProjects().then(setProjects);
  }, []);

  useEffect(() => {
    if (replaceAssetId) {
      if (replaceAssetId === 'ground') {
        setImportType('ground');
      } else if (replaceAssetId === 'ocean') {
        setImportType('ocean');
      } else {
        setImportType('object');
      }
      setIsImportModalOpen(true);
      setError(null);
    }
  }, [replaceAssetId]);

  const closeModal = () => {
    setIsImportModalOpen(false);
    if (setReplaceAssetId) setReplaceAssetId(null);
  };

  const openModal = (type: 'ground' | 'ocean' | 'object') => {
    setImportType(type);
    setIsImportModalOpen(true);
    setError(null);
  };

  const handleImportGroundOrOcean = async (task: Task, type: 'ground' | 'ocean') => {
    setIsLoading(true);
    setError(null);
    try {
      if (!task.nodes) throw new Error("Workspace is empty.");
      
      const hexSlicerNode = task.nodes.find(n => n.type === 'isometricHexSlicer');
      if (!hexSlicerNode || !hexSlicerNode.data.slices || hexSlicerNode.data.slices.length === 0) {
        throw new Error("No extracted tiles found in this workspace.");
      }

      const newAsset = {
        taskId: task.id,
        taskName: task.name,
        type: type,
        slices: hexSlicerNode.data.slices
      };

      if (type === 'ground') {
        setGroundAsset(newAsset);
        setActiveSelection({ type: 'ground' });
      } else {
        setOceanAsset(newAsset);
        setActiveSelection({ type: 'ocean' });
      }
      closeModal();
    } catch (err: any) {
      setError(err.message || "Failed to import asset.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleImportObject = async (task: Task, node: any) => {
    setIsLoading(true);
    setError(null);
    try {
      const imageUrl = node.data.resultUrl || node.data.imageUrl;
      if (!imageUrl) throw new Error("This node has no generated image yet.");
      
      if (replaceAssetId) {
        setObjectAssets(objectAssets.map(a => a.id === replaceAssetId ? {
          ...a,
          taskId: task.id,
          taskName: task.name,
          nodeId: node.id,
          nodePrompt: node.data.localPrompt || "Generated Object",
          imageUrl
        } : a));
        setActiveSelection({ type: 'object', id: replaceAssetId });
      } else {
        const newId = Math.random().toString(36).substr(2, 9);
        const newAsset: ObjectAsset = {
          id: newId,
          taskId: task.id,
          taskName: task.name,
          nodeId: node.id,
          nodePrompt: node.data.localPrompt || "Generated Object",
          imageUrl,
          amount: 5,
          allowOnEdge: false,
          scale: 1.0,
          seedOffset: 0,
          baseTiles: [{lx: 0, ly: 0}]
        };
        
        setObjectAssets([...objectAssets, newAsset]);
        setActiveSelection({ type: 'object', id: newId });
      }
      closeModal();
    } catch (err: any) {
      setError(err.message || "Failed to import asset.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      const newId = Math.random().toString(36).substr(2, 9);
      const newAsset: ObjectAsset = {
        id: newId,
        taskId: 'local',
        taskName: 'Local Upload',
        nodeId: 'local',
        nodePrompt: file.name,
        name: file.name,
        imageUrl: base64,
        amount: 5,
        allowOnEdge: false,
        scale: 1.0,
        seedOffset: 0,
        baseTiles: [{lx: 0, ly: 0}]
      };
      setObjectAssets([...objectAssets, newAsset]);
      setActiveSelection({ type: 'object', id: newId });
    };
    reader.readAsDataURL(file);
    
    e.target.value = '';
  };

  return (
    <div className="flex flex-col h-full bg-[#1a1525]">
      <div className="p-4 border-b border-[var(--color-blender-border)] flex items-center justify-between">
        <h2 className="text-lg font-bold text-white flex items-center gap-2">
          <Folder className="w-5 h-5 text-emerald-400" />
          Assets
        </h2>
        <button 
          onClick={() => setActiveSelection({ type: 'map' })}
          className={`p-1.5 rounded transition-colors ${activeSelection.type === 'map' ? 'bg-blue-600/30 text-blue-300' : 'text-gray-400 hover:text-white hover:bg-white/10'}`}
          title="Map Settings"
        >
          <Settings className="w-4 h-4" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-3 space-y-4">
        {/* Ground Asset Section */}
        <div>
          <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 px-1">Ground Tileset</h3>
          
          {groundAsset ? (
            <button 
              onClick={() => setActiveSelection({ type: 'ground' })}
              className={`w-full text-left bg-black/40 border rounded-lg p-2 transition-all flex items-center gap-3 ${
                activeSelection.type === 'ground' ? 'border-emerald-500/60 bg-emerald-900/20' : 'border-transparent hover:border-emerald-500/30'
              }`}
            >
              <div className="w-10 h-10 bg-black/50 rounded flex items-center justify-center shrink-0 border border-emerald-500/20 overflow-hidden">
                 {groundAsset.slices[0] ? <img alt="image" src={groundAsset.slices[0].url} className="w-8 h-8 object-contain" /> : null}
              </div>
              <div className="min-w-0">
                <div className="text-sm font-medium text-emerald-100 truncate">{groundAsset.taskName}</div>
                <div className="text-[10px] text-gray-500">13 Tiles</div>
              </div>
            </button>
          ) : (
            <button 
              onClick={() => openModal('ground')}
              className="w-full bg-black/20 border border-dashed border-gray-600 hover:border-emerald-500/50 rounded-lg p-3 text-center text-gray-400 hover:text-emerald-400 transition-colors flex items-center justify-center gap-2 text-xs"
            >
              <Plus className="w-4 h-4" /> Import Ground
            </button>
          )}
        </div>

        {/* Ocean Asset Section */}
        <div>
          <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 px-1">Ocean Floor</h3>
          
          {oceanAsset ? (
            <button 
              onClick={() => setActiveSelection({ type: 'ocean' })}
              className={`w-full text-left bg-black/40 border rounded-lg p-2 transition-all flex items-center gap-3 ${
                activeSelection.type === 'ocean' ? 'border-blue-500/60 bg-blue-900/20' : 'border-transparent hover:border-blue-500/30'
              }`}
            >
              <div className="w-10 h-10 bg-black/50 rounded flex items-center justify-center shrink-0 border border-blue-500/20 overflow-hidden">
                 {oceanAsset.slices[0] ? <img alt="image" src={oceanAsset.slices[0].url} className="w-8 h-8 object-contain" /> : null}
              </div>
              <div className="min-w-0">
                <div className="text-sm font-medium text-blue-100 truncate">{oceanAsset.taskName}</div>
                <div className="text-[10px] text-gray-500">Flat Floor</div>
              </div>
            </button>
          ) : (
            <button 
              onClick={() => openModal('ocean')}
              className="w-full bg-black/20 border border-dashed border-gray-600 hover:border-blue-500/50 rounded-lg p-3 text-center text-gray-400 hover:text-blue-400 transition-colors flex items-center justify-center gap-2 text-xs"
            >
              <Plus className="w-4 h-4" /> Import Ocean
            </button>
          )}
        </div>

        {/* Object Assets Section */}
        <div>
          <h3 className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2 px-1">Objects</h3>
          
          <div className="space-y-1 mb-2">
            {objectAssets.map(asset => {
              const isSelected = activeSelection.type === 'object' && activeSelection.id === asset.id;
              return (
                <button 
                  key={asset.id}
                  onClick={() => setActiveSelection({ type: 'object', id: asset.id })}
                  className={`w-full text-left bg-black/40 border rounded-lg p-2 transition-all flex items-center gap-3 ${
                    isSelected ? 'border-indigo-500/60 bg-indigo-900/20' : 'border-transparent hover:border-indigo-500/30'
                  }`}
                >
                  <div className="w-10 h-10 bg-black/50 rounded flex items-center justify-center shrink-0 border border-indigo-500/20 overflow-hidden">
                    <img alt="image" src={asset.imageUrl} className="w-full h-full object-contain" />
                  </div>
                  <div className="min-w-0">
                    <div className="text-sm font-medium text-indigo-100 truncate" title={asset.name || asset.nodePrompt}>{asset.name || asset.nodePrompt}</div>
                    <div className="text-[10px] text-gray-500 truncate">{asset.amount} instances</div>
                  </div>
                </button>
              );
            })}
          </div>

          <div className="flex gap-2">
            <button 
              onClick={() => openModal('object')}
              className="flex-1 bg-indigo-600/20 hover:bg-indigo-600/40 text-indigo-300 text-xs py-2 rounded-lg flex items-center justify-center gap-1 transition-colors border border-indigo-500/30"
            >
              <Plus className="w-3 h-3" /> Add Object
            </button>
            <label className="flex-1 bg-emerald-600/20 hover:bg-emerald-600/40 text-emerald-300 text-xs py-2 rounded-lg flex items-center justify-center gap-1 transition-colors border border-emerald-500/30 cursor-pointer">
              <Upload className="w-3 h-3" /> Upload
              <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </div>

      {/* Import Modal */}
      {isImportModalOpen && (
        <div className="absolute inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-[var(--color-blender-panel)] border border-[var(--color-blender-border)] rounded-xl w-full max-w-md shadow-2xl flex flex-col max-h-[80vh]">
            <div className="p-4 border-b border-[var(--color-blender-border)] flex justify-between items-center">
              <h3 className="font-bold text-lg text-white">
                {replaceAssetId ? 'Replace Object Asset' : `Import ${importType === 'ground' ? 'Ground Tileset' : 'Object Asset'}`}
              </h3>
              <button onClick={closeModal} className="text-gray-400 hover:text-white">✕</button>
            </div>
            
            <div className="p-4 overflow-y-auto flex-1 space-y-4">
              {error && <div className="p-3 bg-red-900/30 border border-red-500/50 rounded text-red-200 text-sm">{error}</div>}
              
              {projects.map(project => (
                <div key={project.id} className="space-y-2">
                  <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wider">{project.name}</h4>
                  {project.tasks.map(task => {
                    if (!task.nodes) return null;
                    
                    if (importType === 'ground' || importType === 'ocean') {
                      const hasGround = task.nodes.some(n => n.type === 'isometricHexSlicer');
                      if (!hasGround) return null;
                      
                      const themeColor = importType === 'ground' ? 'emerald' : 'blue';
                      
                      return (
                        <button
                          key={task.id}
                          onClick={() => handleImportGroundOrOcean(task, importType)}
                          disabled={isLoading}
                          className={`w-full text-left p-3 rounded bg-black/20 border border-transparent hover:border-${themeColor}-500/40 hover:bg-black/40 transition-all flex items-center justify-between group`}
                        >
                          <span className={`text-sm text-gray-300 group-hover:text-${themeColor}-100`}>{task.name}</span>
                          <Check className={`w-4 h-4 text-${themeColor}-500 opacity-0 group-hover:opacity-100`} />
                        </button>
                      );
                    } else {
                      const objectNodes = task.nodes.filter(n => n.data && (n.data.resultUrl || n.data.imageUrl));
                      if (objectNodes.length === 0) return null;
                      
                      return (
                        <div key={task.id} className="bg-black/20 rounded p-2 border border-gray-800">
                          <div className="text-xs text-gray-400 mb-2 px-1">{task.name}</div>
                          <div className="grid grid-cols-4 gap-2">
                            {objectNodes.map(node => {
                              const imageUrl = node.data.resultUrl || node.data.imageUrl;
                              const isAlreadyImported = objectAssets.some(a => a.nodeId === node.id);
                              return (
                                <button
                                  key={node.id}
                                  onClick={() => handleImportObject(task, node)}
                                  disabled={isLoading || !imageUrl}
                                  className={`aspect-square relative rounded border transition-all flex items-center justify-center group disabled:opacity-50 disabled:cursor-not-allowed overflow-hidden ${
                                    isAlreadyImported 
                                      ? 'bg-emerald-900/30 border-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.3)]' 
                                      : 'bg-black/40 border-transparent hover:border-indigo-500/60 hover:bg-indigo-900/40'
                                  }`}
                                >
                                  {imageUrl ? (
                                    <img alt="image" src={imageUrl} className="w-full h-full object-contain p-1" />
                                  ) : (
                                    <span className="text-[8px] text-gray-600">No Img</span>
                                  )}
                                  
                                  {isAlreadyImported && (
                                    <div className="absolute top-1 right-1 bg-emerald-500 text-black rounded-full p-0.5">
                                      <Check className="w-2.5 h-2.5" />
                                    </div>
                                  )}

                                  <div className="absolute inset-0 bg-indigo-500/20 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Plus className="w-4 h-4 text-white" />
                                  </div>
                                </button>
                              );
                            })}
                          </div>
                        </div>
                      );
                    }
                  })}
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import AssetManager from "./AssetManager";
import MapPreview from "./MapPreview";
import ParameterUI from "./ParameterUI";
import { getTask, saveMapData } from "@/lib/store";
import { useHistory } from "@/lib/useHistory";
import { TerrainGenerator } from "@/lib/map-engine/TerrainGenerator";

export interface MapAsset {
  taskId: string;
  taskName: string;
  type: 'ground' | 'ocean';
  slices: {name: string, url: string}[];
}

export interface ObjectAsset {
  id: string;
  taskId: string;
  taskName: string;
  nodeId: string;
  nodePrompt: string;
  name?: string;
  imageUrl: string;
  amount: number;
  allowOnEdge: boolean;
  scale: number;
  seedOffset?: number;
  baseTiles?: {lx: number, ly: number}[];
  gridOffset?: {x: number, y: number};
  shadowEnabled?: boolean;
  shadowMethod?: string;
  shadowBlur?: number;
  shadowFade?: number;
  shadowSkew?: number;
  shadowOpacity?: number;
  shadowScaleX?: number; // legacy
  shadowScaleY?: number;
  shadowOffsetX?: number;
  shadowOffsetY?: number;
  shadowImageUrl?: string;
  shadowAnchorX?: number;
  shadowAnchorY?: number;
  shadowWidth?: number;
  shadowHeight?: number;
}

export interface MapParameters {
  canvasWidth: number;
  canvasHeight: number;
  islandWidth: number;
  islandHeight: number;
  seed: number;
  noiseScale: number;
  oceanTaperLevels: number;
  oceanDimAmount: number;
  oceanAddFoam?: boolean;
  oceanFoamColor?: { h: number, s: number, l: number };
  oceanTaperWidths?: Record<number, number>;
}

export type SelectionState = { type: 'map' } | { type: 'ground' } | { type: 'ocean' } | { type: 'object', id: string, instanceId?: string };

export type InstanceOverride = { cellX: number, cellY: number, lx: number, ly: number, deleted?: boolean, layer?: number };

export interface MapState {
  groundAsset: MapAsset | null;
  oceanAsset: MapAsset | null;
  objectAssets: ObjectAsset[];
  parameters: MapParameters;
  instanceOverrides: Record<string, InstanceOverride>;
  groundOverrides: Record<string, number>;
  oceanOverrides: Record<string, number>;
}

export default function MapGeneratorWorkspace({ taskId }: { taskId: string }) {
  const { state: mapState, set: setMapState, undo, redo, canUndo, canRedo } = useHistory<MapState>({
    groundAsset: null,
    oceanAsset: null,
    objectAssets: [],
    parameters: {
      canvasWidth: 20,
      canvasHeight: 20,
      islandWidth: 16,
      islandHeight: 16,
      seed: 12345,
      noiseScale: 0.1,
      oceanTaperLevels: 0,
      oceanDimAmount: 0.5,
      oceanAddFoam: false,
      oceanFoamColor: { h: 63, s: 70, l: 90 }
    },
    instanceOverrides: {},
    groundOverrides: {},
    oceanOverrides: {}
  });

  const [activeSelection, setActiveSelection] = useState<SelectionState>({ type: 'map' });
  const [replaceAssetId, setReplaceAssetId] = useState<string | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);

  const [activeTool, setActiveTool] = useState<'select' | 'paint' | 'erase'>('select');
  const [activeLevel, setActiveLevel] = useState<number>(1);
  const [levels, setLevels] = useState<number[]>([1]);

  // Load from store on mount
  useEffect(() => {
    const loadData = async () => {
      const task = await getTask(taskId);
      if (task && task.mapData) {
        let p = task.mapData.parameters || { canvasWidth: 20, canvasHeight: 20, islandWidth: 16, islandHeight: 16, seed: 12345, noiseScale: 0.1, oceanTaperLevels: 0, oceanDimAmount: 0.5, oceanAddFoam: false };
        if (p.width !== undefined) {
           // Migrate old data
           p = {
             canvasWidth: p.width,
             canvasHeight: p.height,
             islandWidth: Math.floor(p.width / 2),
             islandHeight: Math.floor(p.height / 2),
             seed: p.seed,
             noiseScale: p.noiseScale
           };
        }
        setMapState({
          groundAsset: task.mapData.groundAsset || null,
          oceanAsset: task.mapData.oceanAsset || null,
          objectAssets: task.mapData.objectAssets || [],
          parameters: p,
          instanceOverrides: task.mapData.instanceOverrides || {},
          groundOverrides: task.mapData.groundOverrides || {},
          oceanOverrides: task.mapData.oceanOverrides || {}
        });
        if (task.mapData.levels) {
          setLevels(task.mapData.levels);
        }
      }
      setIsLoaded(true);
    };
    loadData();
  }, [taskId, setMapState]);

  useEffect(() => {
    if (!isLoaded || !taskId) return;
    const saveTimer = setTimeout(() => {
      saveMapData(taskId, mapState);
    }, 500); // Debounce save
    return () => clearTimeout(saveTimer);
  }, [mapState, isLoaded, taskId]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && !e.shiftKey && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        undo();
      } else if (e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 'z') {
        e.preventDefault();
        redo();
      } else if (e.ctrlKey && e.key.toLowerCase() === 'y') {
        e.preventDefault();
        redo();
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        // Handle delete selected asset
        if (activeSelection.type === 'object') {
          setMapState(prev => ({
            ...prev,
            instanceOverrides: {
              ...prev.instanceOverrides,
              [activeSelection.id]: {
                ...(prev.instanceOverrides[activeSelection.id] || { cellX: 0, cellY: 0, lx: 0, ly: 0 }),
                deleted: true
              }
            }
          }));
          setActiveSelection({ type: 'map' });
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo, activeSelection, setMapState]);

  const setGroundAsset = useCallback((val: any) => setMapState(p => ({ ...p, groundAsset: typeof val === 'function' ? val(p.groundAsset) : val })), [setMapState]);
  const setOceanAsset = useCallback((val: any) => setMapState(p => ({ ...p, oceanAsset: typeof val === 'function' ? val(p.oceanAsset) : val })), [setMapState]);
  const setObjectAssets = useCallback((val: any) => setMapState(p => ({ ...p, objectAssets: typeof val === 'function' ? val(p.objectAssets) : val })), [setMapState]);
  const setParameters = useCallback((val: any) => setMapState(p => ({ ...p, parameters: typeof val === 'function' ? val(p.parameters) : val })), [setMapState]);
  const setInstanceOverrides = useCallback((val: any) => setMapState(p => ({ ...p, instanceOverrides: typeof val === 'function' ? val(p.instanceOverrides) : val })), [setMapState]);
  const setGroundOverrides = useCallback((val: any) => setMapState(p => ({ ...p, groundOverrides: typeof val === 'function' ? val(p.groundOverrides) : val })), [setMapState]);
  const setOceanOverrides = useCallback((val: any) => setMapState(p => ({ ...p, oceanOverrides: typeof val === 'function' ? val(p.oceanOverrides) : val })), [setMapState]);

  const handleSpawnObjects = useCallback((assetId: string, amount: number) => {
    if (!amount || amount <= 0) return;
    const asset = mapState.objectAssets.find(a => a.id === assetId);
    if (!asset) return;

    const rawGridLevels = TerrainGenerator.generate(
      mapState.parameters.canvasWidth,
      mapState.parameters.canvasHeight,
      mapState.parameters.islandWidth,
      mapState.parameters.islandHeight,
      mapState.parameters.seed,
      mapState.parameters.noiseScale,
      [], // no procedural objects
      mapState.groundOverrides,
      levels
    );

    const occupancy = new Set<string>();
    Object.values(mapState.instanceOverrides).forEach((override: any) => {
      if (!override.deleted) {
        const oAsset = mapState.objectAssets.find(a => a.id === override.assetId);
        const tiles = oAsset?.baseTiles || [{lx: 0, ly: 0}];
        tiles.forEach(t => {
           occupancy.add(`${override.cellX * 3 + override.lx + t.lx + 1},${override.cellY * 3 + override.ly + t.ly + 1}`);
        });
      }
    });

    const isSlotValid = (gx: number, gy: number) => {
        const cx = Math.floor(gx / 3);
        const cy = Math.floor(gy / 3);
        if (cy < 0 || cy >= mapState.parameters.canvasHeight || cx < 0 || cx >= mapState.parameters.canvasWidth) return false;

        let topLevel = 1;
        for (const lvl of levels) {
           if (rawGridLevels[lvl]?.[cy]?.[cx]?.isLand) topLevel = lvl;
        }

        const cell = rawGridLevels[topLevel]?.[cy]?.[cx];
        if (!cell || !cell.isLand) return false;
        return !occupancy.has(`${gx},${gy}`);
    };

    const rawBaseTiles = asset.baseTiles && asset.baseTiles.length > 0 ? asset.baseTiles : [{lx: 0, ly: 0}];
    const limit = Math.floor(1.5 * (asset.scale || 1.0));
    let baseTiles = rawBaseTiles.filter((t: {lx: number, ly: number}) => Math.abs(t.lx) <= limit && Math.abs(t.ly) <= limit);
    if (baseTiles.length === 0) baseTiles = [{lx: 0, ly: 0}];

    const availablePositions: {gx: number, gy: number}[] = [];
    for (let gy = 0; gy < mapState.parameters.canvasHeight * 3; gy++) {
      for (let gx = 0; gx < mapState.parameters.canvasWidth * 3; gx++) {
         let canPlace = true;
         for (const tile of baseTiles) {
           const tgx = gx + tile.lx;
           const tgy = gy + tile.ly;
           if (!isSlotValid(tgx, tgy)) {
             canPlace = false;
             break;
           }
         }
         if (canPlace) availablePositions.push({gx, gy});
      }
    }

    const newOverrides = { ...mapState.instanceOverrides };
    let placed = 0;
    while (placed < amount && availablePositions.length > 0) {
      const randIdx = Math.floor(Math.random() * availablePositions.length);
      const pos = availablePositions[randIdx];

      let stillValid = true;
      for (const tile of baseTiles) {
         if (occupancy.has(`${pos.gx + tile.lx},${pos.gy + tile.ly}`)) {
           stillValid = false;
           break;
         }
      }

      if (stillValid) {
         const cx = Math.floor(pos.gx / 3);
         const cy = Math.floor(pos.gy / 3);
         const lx = pos.gx - cx * 3 - 1;
         const ly = pos.gy - cy * 3 - 1;

         let topLevel = 1;
         for (const lvl of levels) {
            if (rawGridLevels[lvl]?.[cy]?.[cx]?.isLand) topLevel = lvl;
         }

         const newId = `spawned_${Date.now()}_${Math.floor(Math.random()*1000)}`;
         newOverrides[newId] = {
           cellX: cx,
           cellY: cy,
           lx, ly,
           layer: topLevel,
           assetId: assetId
         } as any;

         for (const tile of baseTiles) {
           occupancy.add(`${pos.gx + tile.lx},${pos.gy + tile.ly}`);
         }
         placed++;
      }

      availablePositions.splice(randIdx, 1);
    }

    setInstanceOverrides(newOverrides);

  }, [mapState, levels, setInstanceOverrides]);

  if (!isLoaded) return null;

  return (
    <div className="flex h-full w-full bg-[var(--color-blender-bg)] overflow-hidden text-gray-200">
      {/* Left Panel: Assets */}
      <div className="w-72 border-r border-[var(--color-blender-border)] bg-[var(--color-blender-panel)] flex flex-col h-full shrink-0 z-10 shadow-[4px_0_12px_rgba(0,0,0,0.5)]">
        <AssetManager 
          groundAsset={mapState.groundAsset} 
          setGroundAsset={setGroundAsset} 
          oceanAsset={mapState.oceanAsset}
          setOceanAsset={setOceanAsset}
          objectAssets={mapState.objectAssets}
          setObjectAssets={setObjectAssets}
          activeSelection={activeSelection}
          setActiveSelection={setActiveSelection}
          replaceAssetId={replaceAssetId}
          setReplaceAssetId={setReplaceAssetId}
        />
      </div>

      {/* Center Panel: Map Preview */}
      <div className="flex-1 overflow-hidden">
        {mapState.groundAsset ? (
          <MapPreview 
            groundAsset={mapState.groundAsset}
            oceanAsset={mapState.oceanAsset}
            objectAssets={mapState.objectAssets}
            parameters={mapState.parameters} 
            instanceOverrides={mapState.instanceOverrides}
            setInstanceOverrides={setInstanceOverrides}
            groundOverrides={mapState.groundOverrides}
            setGroundOverrides={setGroundOverrides}
            oceanOverrides={mapState.oceanOverrides}
            setOceanOverrides={setOceanOverrides}
            activeSelection={activeSelection}
            setActiveSelection={setActiveSelection}
            activeTool={activeTool}
            setActiveTool={setActiveTool}
            activeLevel={activeLevel}
            setActiveLevel={setActiveLevel}
            levels={levels}
            setLevels={setLevels}
            setParameters={(p) => {
              setParameters(p);
              setInstanceOverrides({}); // Clear overrides on map change
              setGroundOverrides({});
            }}
          />
        ) : (
          <div className="flex h-full items-center justify-center text-gray-500">
            Select a ground asset to begin
          </div>
        )}
      </div>

      {/* Right Panel: Parameters */}
      <div className="w-80 border-l border-[var(--color-blender-border)] bg-[var(--color-blender-panel)] flex flex-col h-full shrink-0 z-10 shadow-[-4px_0_12px_rgba(0,0,0,0.5)]">
        <ParameterUI 
          parameters={mapState.parameters} 
          setParameters={setParameters} 
          groundAsset={mapState.groundAsset}
          setGroundAsset={setGroundAsset}
          oceanAsset={mapState.oceanAsset}
          setOceanAsset={setOceanAsset}
          objectAssets={mapState.objectAssets}
          setObjectAssets={setObjectAssets}
          activeSelection={activeSelection}
          onRequestReplaceNode={(id) => setReplaceAssetId(id)}
          hasManualEdits={Object.keys(mapState.instanceOverrides).length > 0 || Object.keys(mapState.groundOverrides).length > 0}
          onClearManualEdits={() => {
            setInstanceOverrides({});
            setGroundOverrides({});
          }}
          onSpawnObjects={handleSpawnObjects}
          onClearOceanOverrides={(lvl) => {
            setOceanOverrides((prev: Record<string, number>) => {
              const next = { ...prev };
              Object.keys(next).forEach(k => {
                if (next[k] === lvl) delete next[k];
              });
              return next;
            });
          }}
        />
      </div>
    </div>
  );
}

import { useEffect, useRef, useState, PointerEvent } from "react";
import { MapAsset, ObjectAsset, MapParameters, InstanceOverride, SelectionState } from "./MapGeneratorWorkspace";
import { TerrainGenerator, MapGridCell, PlacedObject } from "@/lib/map-engine/TerrainGenerator";
import { Loader2, Grid3X3, AlertTriangle, MousePointer2, Paintbrush, Eraser, Eye, EyeOff, Layers, Trash2 } from "lucide-react";

interface MapPreviewProps {
  groundAsset: MapAsset | null;
  objectAssets: ObjectAsset[];
  parameters: MapParameters;
  instanceOverrides: Record<string, InstanceOverride>;
  setInstanceOverrides: (overrides: Record<string, InstanceOverride> | ((prev: Record<string, InstanceOverride>) => Record<string, InstanceOverride>)) => void;
  groundOverrides: Record<string, number>;
  setGroundOverrides: (overrides: Record<string, number> | ((prev: Record<string, number>) => Record<string, number>)) => void;
  oceanAsset?: MapAsset | null;
  setParameters: (p: MapParameters) => void;
  oceanOverrides?: Record<string, number>;
  setOceanOverrides?: (overrides: Record<string, number> | ((prev: Record<string, number>) => Record<string, number>)) => void;
  activeSelection?: SelectionState;
  setActiveSelection?: (s: SelectionState) => void;
  activeTool: 'select' | 'paint' | 'erase';
  setActiveTool: (t: 'select' | 'paint' | 'erase') => void;
