        {activeSelection.type === 'map' && renderMapSettings()}
        {activeSelection.type === 'ground' && renderGroundSettings()}
        {activeSelection.type === 'ocean' && renderOceanSettings()}
        {activeSelection.type === 'object' && renderObjectSettings(activeSelection.id)}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Handle, Position, useReactFlow } from "reactflow";
import { ImageIcon, RefreshCw, Play, AlertCircle, ChevronDown, Eye, PenTool } from "lucide-react";
import { queueImageGen, getTaskStatus, uploadMediaDirect, fetchNodePrompt } from "@/lib/plenxai";

const MODELS = [
  { id: "nano-banana-pro", name: "Nano Banana PRO" },
  { id: "kling-o1-image", name: "Kling O1 Image" },
  { id: "flux-2-pro", name: "Flux 2 Pro" },
];

const RESOLUTIONS = [
  { id: "1k", name: "1K Resolution" },
  { id: "2k", name: "2K Resolution" },
  { id: "4k", name: "4K Resolution" },
  { id: "8k", name: "8K Resolution" }
];

export default function AssetGeneratorNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [status, setStatus] = useState<"idle" | "queueing" | "polling" | "diffing" | "succeeded" | "failed">("idle");
  const [resultUrl, setResultUrl] = useState<string | null>(data.resultUrl || null);
  const [basePreviewUrl, setBasePreviewUrl] = useState<string | null>(data.basePreviewUrl || null);
  const [error, setError] = useState<string | null>(null);
  const [selectedModel, setSelectedModel] = useState<string>(data.model || MODELS[0].id);
  const [isModelMenuOpen, setIsModelMenuOpen] = useState(false);
  const [selectedResolution, setSelectedResolution] = useState<string>(data.resolution || RESOLUTIONS[0].id);
  const [isResolutionMenuOpen, setIsResolutionMenuOpen] = useState(false);
  const [localPrompt, setLocalPrompt] = useState<string>(data.localPrompt || "");
  const [showApiPrompt, setShowApiPrompt] = useState(false);
  const [apiPromptPreview, setApiPromptPreview] = useState<string>(data.apiPromptPreview || "");
  
  const [threshold, setThreshold] = useState<number>(data.threshold || 30);
  const [generatedUrl, setGeneratedUrl] = useState<string | null>(data.generatedUrl || null);
  
  const { getNodes, getEdges, setNodes } = useReactFlow();

  const performChromaKey = (generatedImgUrl: string, currentThreshold: number = threshold): Promise<string> => {
    return new Promise((resolve, reject) => {
      const genImg = new Image();
      genImg.crossOrigin = "anonymous";

      genImg.onload = () => {
        try {
          const canvas = document.createElement("canvas");
          const w = genImg.width;
          const h = genImg.height;
          canvas.width = w;
          canvas.height = h;
          
          const ctx = canvas.getContext("2d")!;
          ctx.drawImage(genImg, 0, 0);
          const genData = ctx.getImageData(0, 0, w, h);
          const outData = new Uint8ClampedArray(genData.data);
          
          for (let i = 0; i < outData.length; i += 4) {
            const r = outData[i];
            const g = outData[i+1];
            const b = outData[i+2];
            
            const rDist = Math.abs(r - 255);
            const gDist = Math.abs(g - 0);
            const bDist = Math.abs(b - 255);
            
            // Pass 1: Key out strict neon green (#00FF00)
            if (rDist < currentThreshold && gDist < currentThreshold && bDist < currentThreshold) {
              outData[i+3] = 0;
            }
          }

          // Pass 2: Edge Defringing (Color Bleed)
          // Find remaining pixels that are "contaminated" by neon green
          // and replace their color with the nearest "pure" object pixel.
          const defringedData = new Uint8ClampedArray(outData);
          const radius = 3;
          
          for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
              const idx = (y * w + x) * 4;
              
              if (outData[idx+3] > 0) { // If pixel survived the key
                const r = outData[idx];
                const g = outData[idx+1];
                const b = outData[idx+2];
                
                // Contamination heuristic: Red and Blue are significantly higher than Green
                const isContaminated = (r - g > 40 && b - g > 40);
                
                if (isContaminated) {
                  let foundR = r, foundG = g, foundB = b;
                  let minDistance = 9999;
                  
                  // Search local neighborhood for a pure pixel
                  for (let dy = -radius; dy <= radius; dy++) {
                    for (let dx = -radius; dx <= radius; dx++) {
                      const ny = y + dy;
                      const nx = x + dx;
                      if (ny >= 0 && ny < h && nx >= 0 && nx < w) {
                        const nIdx = (ny * w + nx) * 4;
                        if (outData[nIdx+3] > 0) {
                          const nr = outData[nIdx];
                          const ng = outData[nIdx+1];
                          const nb = outData[nIdx+2];
                          const nContaminated = (nr - ng > 30 && nb - ng > 30);
                          
                          if (!nContaminated) {
                            const dist = dx*dx + dy*dy;
                            if (dist < minDistance) {
                              minDistance = dist;
                              foundR = nr;
                              foundG = ng;
                              foundB = nb;
                            }
                          }
                        }
                      }
                    }
                  }
                  
                  defringedData[idx] = foundR;
                  defringedData[idx+1] = foundG;
                  defringedData[idx+2] = foundB;
                }
              }
            }
          }
          
          let minX = w, minY = h, maxX = 0, maxY = 0;
          let hasVisiblePixels = false;
          for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
              const idx = (y * w + x) * 4;
              if (defringedData[idx+3] > 0) {
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
                hasVisiblePixels = true;
              }
            }
          }

          ctx.putImageData(new ImageData(defringedData, w, h), 0, 0);

          if (hasVisiblePixels) {
            const trimmedW = maxX - minX + 1;
            const trimmedH = maxY - minY + 1;
            const trimmedCanvas = document.createElement("canvas");
            trimmedCanvas.width = trimmedW;
            trimmedCanvas.height = trimmedH;
            const trimmedCtx = trimmedCanvas.getContext("2d")!;
            trimmedCtx.drawImage(canvas, minX, minY, trimmedW, trimmedH, 0, 0, trimmedW, trimmedH);
            resolve(trimmedCanvas.toDataURL("image/png"));
          } else {
            resolve(canvas.toDataURL("image/png"));
          }
        } catch (e) {
          reject(e);
        }
      };

      genImg.onerror = reject;
      genImg.src = generatedImgUrl;
    });
  };

  const generateAsset = async () => {
    const nodes = getNodes();
    const edges = getEdges();
    const incomingEdges = edges.filter(e => e.target === id);
    
    const promptParts: string[] = [];
    if (localPrompt) promptParts.push(localPrompt);

    let styleInput = "";
    let inputImageUrl = "";
    let secondaryImageUrl = "";
    incomingEdges.forEach(edge => {
      const sourceNode = nodes.find(n => n.id === edge.source);
      if (!sourceNode) return;
      if (edge.targetHandle === 'text') {
        const text = sourceNode.data.refinedText || sourceNode.data.text || sourceNode.data.bakedStyle || "";
        if (text) promptParts.push(text);
      }
      if (edge.targetHandle === 'style') {
        styleInput = sourceNode.data.refinedText || sourceNode.data.text || sourceNode.data.bakedStyle || "";
      }
      if (edge.targetHandle === 'image') {
        inputImageUrl = sourceNode.data.imageUrl || sourceNode.data.resultUrl || sourceNode.data.image || "";
      }
      if (edge.targetHandle === 'image-2') {
        secondaryImageUrl = sourceNode.data.imageUrl || sourceNode.data.resultUrl || sourceNode.data.image || "";
      }
    });

    if (!inputImageUrl) {
      setError("Please connect a Base Island image.");
      setStatus("failed");
      return;
    }

    const objectPrompt = promptParts.join(", ") || "object";
    const styleString = styleInput ? ` Artstyle: ${styleInput}` : "";
    
    let baseApiPrompt = await fetchNodePrompt('AssetGeneratorNode');
    if (!baseApiPrompt) {
      baseApiPrompt = `You are an artist in the game industry. Generate {object} that would visually match and perfectly sit in the middle of this island. Isolate the {object} and make the background neon green for color keying (#00FF00). IMPORTANT: PRESERVE THE ARTSTYLE AND LIGHTING, DO NOT INCLUDE COMPONENTS FROM REFERENCE IN THE GENERATED IMAGE. USE THe IMAGE 2 AS REFERENCE FOR THE {object}.
Subject: A single isolated {object} rendered in a strict 30-degree isometric perspective.
Style: {style}
Composition: The {object} must be centered, filling 70% of the canvas. DO NOT include the island base or any terrain from the reference image. Generate the {object} as a standalone floating sprite.
Technical Output: Place the object on a solid, flat neon green background (#00FF00). IMPORTANT: Ensure there are no ground shadows, no floor planes, and no "color spill" or neon green glow reflected onto the object. The edges must be sharp and clean for pixel extraction.
Reference: {reference image}.
Spec: resolution:{resolution}. ratio 1:1.`;
    }
    
    const apiPrompt = baseApiPrompt
      .replace(/{object}/g, objectPrompt)
      .replace(/{style}/g, styleString)
      .replace(/1k resolution/gi, `${selectedResolution} resolution`)
      .replace(/{resolution}/gi, selectedResolution);
    
    setApiPromptPreview(apiPrompt);
    setBasePreviewUrl(inputImageUrl);

    const apiKey = localStorage.getItem("artist-assistant-image-api");
    if (!apiKey) {
      setError("Please enter PlenxAI API Key in Settings.");
      setStatus("failed");
      return;
    }

    if (!objectPrompt) {
      setError("No prompt detected.");
      setStatus("failed");
      return;
    }

    setStatus("queueing");
    setError(null);

    try {
      let additionalReferenceUrl = "";
      if (inputImageUrl.startsWith('data:image/')) {
        const uploadRes = await uploadMediaDirect(apiKey, inputImageUrl);
        additionalReferenceUrl = uploadRes.url || uploadRes.cdn_url;
      } else if (inputImageUrl.startsWith('blob:')) {
        const imgRes = await fetch(inputImageUrl);
        const blob = await imgRes.blob();
        const reader = new FileReader();
        const base64Data: string = await new Promise((resolve) => {
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(blob);
        });
        const uploadRes = await uploadMediaDirect(apiKey, base64Data);
        additionalReferenceUrl = uploadRes.url || uploadRes.cdn_url;
      } else if (inputImageUrl.startsWith('http')) {
        additionalReferenceUrl = inputImageUrl;
      }

      if (!additionalReferenceUrl) {
        throw new Error("Failed to upload base image.");
      }

      const refs = [additionalReferenceUrl];
      
      if (secondaryImageUrl) {
        if (secondaryImageUrl.startsWith('data:image/')) {
          const up2 = await uploadMediaDirect(apiKey, secondaryImageUrl);
          refs.push(up2.url || up2.cdn_url);
        } else if (secondaryImageUrl.startsWith('blob:')) {
          const imgRes = await fetch(secondaryImageUrl);
          const blob = await imgRes.blob();
          const reader = new FileReader();
          const base64Data: string = await new Promise((resolve) => {
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(blob);
          });
          const up2 = await uploadMediaDirect(apiKey, base64Data);
          refs.push(up2.url || up2.cdn_url);
        } else if (secondaryImageUrl.startsWith('http')) {
          refs.push(secondaryImageUrl);
        }
      }

      const response = await queueImageGen(apiKey, {
        prompt: apiPrompt,
        model: selectedModel,
        resolution: selectedResolution,
        aspect_ratio: "1:1",
        references_urls: refs
      });

      if (response.success && response.task_id) {
        startPolling(response.task_id, apiKey, additionalReferenceUrl);
      } else {
        setError(response.message || response.error || "Failed to queue generation.");
        setStatus("failed");
      }
    } catch (err: any) {
      setError(err.message || "Network error.");
      setStatus("failed");
    }
  };

  const startPolling = async (taskId: string, apiKey: string, baseImgUrl: string) => {
    setStatus("polling");
    
    const poll = async () => {
      try {
        const res = await getTaskStatus(apiKey, taskId);
        
        const isDone = res.status === 'succeeded' || (res.status as string) === 'completed' || (res.status as string) === 'success' || !!res.result_url;
        
        if (isDone && (res.result_url || (res as any).url || (res as any).image_url)) {
          const fetchedGenUrl = res.result_url || (res as any).url || (res as any).image_url;
          setGeneratedUrl(fetchedGenUrl);
          
          setStatus("diffing");
          // Proceed to chroma key!
          try {
            const extractedAssetUrl = await performChromaKey(fetchedGenUrl, threshold);
            setResultUrl(extractedAssetUrl);
            setStatus("succeeded");
            setNodes(nds => nds.map(n => n.id === id ? { 
              ...n, 
              data: { ...n.data, resultUrl: extractedAssetUrl, imageUrl: extractedAssetUrl, generatedUrl: fetchedGenUrl, threshold } 
            } : n));
          } catch (err) {
            console.error("Chroma key failed after generation:", err);
            setStatus("failed");
          }

          return true;
        } else if (res.status === 'failed' || (res.status as string) === 'error') {
          setError((res as any).error || (res as any).message || "Generation failed.");
          setStatus("failed");
          return true;
        }
        
        return false;
      } catch (err) {
        console.error("Polling error:", err);
        return false; // Keep polling
      }
    };

    const interval = setInterval(async () => {
      const done = await poll();
      if (done) {
        clearInterval(interval);
      }
    }, 3000);
  };

  return (
    <div className={`w-80 bg-[#1a1525] rounded-lg shadow-2xl transition-all duration-200 relative ${
      selected ? "border-2 border-[#fbbf24]" : "border-2 border-indigo-500/30"
    }`}>
      <div className="bg-indigo-900/20 px-4 py-3 flex flex-col items-center border-b border-indigo-500/20 rounded-t-lg">
        <div className="flex items-center justify-between w-full">
          <div className="flex items-center gap-2">
            <PenTool className="w-5 h-5 text-indigo-400" />
            <span className="font-bold text-xs text-indigo-100 uppercase tracking-wider">Asset Gen (Chroma)</span>
          </div>
          {status !== 'idle' && (
            <div className="flex items-center gap-2">
              <span className="text-[10px] uppercase tracking-wider text-blue-400 font-bold animate-pulse">{status}</span>
            </div>
          )}
        </div>
      </div>
      
      <div className="p-4 space-y-3">
        <div className="relative">
          <Handle type="target" position={Position.Left} id="text" className="!w-4 !h-4 !bg-[#3b82f6] !border-none !left-[-24px] top-1/2" />
          <textarea
            className="nodrag text-xs w-full bg-black/40 text-gray-200 p-2 rounded border border-indigo-500/20 focus:border-indigo-500/60 focus:outline-none resize-none"
            placeholder="e.g. 'A wooden crate', 'A patch of green grass'"
            rows={2}
            value={localPrompt}
            onChange={(e) => setLocalPrompt(e.target.value)}
          />
        </div>

        <div className="flex flex-col gap-1">
           <div className="relative flex items-center h-6">
             <Handle type="target" position={Position.Left} id="style" className="!w-4 !h-4 !bg-[#3b82f6] !border-none !left-[-24px]" />
             <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Style Input</span>
           </div>
           <div className="relative flex items-center h-6">
             <Handle type="target" position={Position.Left} id="image" className="!w-4 !h-4 !bg-[#22c55e] !border-none !left-[-24px]" />
             <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Base Island Image</span>
           </div>
           <div className="relative flex items-center h-6">
             <Handle type="target" position={Position.Left} id="image-2" className="!w-4 !h-4 !bg-[#22c55e] !border-none !left-[-24px]" />
             <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Reference Image</span>
           </div>
        </div>

        <div className="space-y-1">
          <div className="flex justify-between items-center">
            <span className="text-[10px] text-indigo-200 font-medium">Key Threshold</span>
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-bold text-indigo-400">{threshold}</span>
              <button 
                onClick={async () => {
                  if (basePreviewUrl && generatedUrl) {
                    try {
                      setStatus("diffing");
                      const extractedAssetUrl = await performChromaKey(generatedUrl, threshold);
                      setResultUrl(extractedAssetUrl);
                      setStatus("succeeded");
                      setNodes(nds => nds.map(n => n.id === id ? { 
                        ...n, 
                        data: { ...n.data, resultUrl: extractedAssetUrl, imageUrl: extractedAssetUrl, threshold } 
                      } : n));
                    } catch (err) {
                      console.error(err);
                      setStatus("failed");
                    }
                  }
                }}
                disabled={!generatedUrl || status === 'diffing' || status === 'queueing' || status === 'polling'}
                className="p-1 bg-indigo-500/20 hover:bg-indigo-500/40 rounded transition-colors disabled:opacity-50"
                title="Force Re-calculate Diff"
              >
                <RefreshCw className="w-3 h-3 text-indigo-300" />
              </button>
            </div>
          </div>
          <input
            type="range"
            min="0"
            max="100"
            value={threshold}
            onChange={async (e) => {
              const newThreshold = parseInt(e.target.value);
              setThreshold(newThreshold);
              
              if (generatedUrl) {
                try {
                  const extractedAssetUrl = await performChromaKey(generatedUrl, newThreshold);
                  setResultUrl(extractedAssetUrl);
                  setNodes(nds => nds.map(n => n.id === id ? { 
                    ...n, 
                    data: { ...n.data, resultUrl: extractedAssetUrl, imageUrl: extractedAssetUrl, threshold: newThreshold } 
                  } : n));
                } catch (err) {
                  console.error(err);
                }
              }
            }}
            className="nodrag w-full h-1 bg-indigo-900/50 rounded-lg appearance-none cursor-pointer accent-indigo-500"
          />
        </div>

        <div className="grid grid-cols-2 gap-2 relative z-20">
          <div className="relative">
            <button 
              onClick={() => { setIsModelMenuOpen(!isModelMenuOpen); setIsResolutionMenuOpen(false); }}
              className="nodrag w-full bg-black/40 border border-indigo-500/20 rounded px-3 py-2 flex items-center justify-between hover:border-indigo-500/40 transition-colors"
            >
              <span className="text-xs text-indigo-100 font-medium truncate pr-2">
                {MODELS.find(m => m.id === selectedModel)?.name || "Model"}
              </span>
              <ChevronDown className={`w-3 h-3 text-indigo-400 transition-transform ${isModelMenuOpen ? 'rotate-180' : ''} shrink-0`} />
            </button>
            
            {isModelMenuOpen && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-[#1a2230] border border-indigo-500/30 rounded shadow-2xl overflow-hidden animate-in fade-in">
                {MODELS.map((m) => (
                  <button
                    key={m.id}
                    onClick={() => {
                      setSelectedModel(m.id);
                      setIsModelMenuOpen(false);
                      setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, model: m.id } } : n));
                    }}
                    className={`w-full px-3 py-2 text-left text-[10px] transition-colors hover:bg-indigo-600/20 ${
                      selectedModel === m.id ? 'text-indigo-400 font-bold bg-indigo-600/10' : 'text-indigo-100/70'
                    }`}
                  >
                    {m.name}
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="relative">
            <button 
              onClick={() => { setIsResolutionMenuOpen(!isResolutionMenuOpen); setIsModelMenuOpen(false); }}
              className="nodrag w-full bg-black/40 border border-indigo-500/20 rounded px-3 py-2 flex items-center justify-between hover:border-indigo-500/40 transition-colors"
            >
              <span className="text-xs text-indigo-100 font-medium truncate pr-2">
                {RESOLUTIONS.find(r => r.id === selectedResolution)?.name || "Res"}
              </span>
              <ChevronDown className={`w-3 h-3 text-indigo-400 transition-transform ${isResolutionMenuOpen ? 'rotate-180' : ''} shrink-0`} />
            </button>
            
            {isResolutionMenuOpen && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-[#1a2230] border border-indigo-500/30 rounded shadow-2xl overflow-hidden animate-in fade-in">
                {RESOLUTIONS.map((r) => (
                  <button
                    key={r.id}
                    onClick={() => {
                      setSelectedResolution(r.id);
                      setIsResolutionMenuOpen(false);
                      setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, resolution: r.id } } : n));
                    }}
                    className={`w-full px-3 py-2 text-left text-[10px] transition-colors hover:bg-indigo-600/20 ${
                      selectedResolution === r.id ? 'text-indigo-400 font-bold bg-indigo-600/10' : 'text-indigo-100/70'
                    }`}
                  >
                    {r.name}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Image Preview */}
        <div 
          className="w-full aspect-square bg-black/50 border border-indigo-500/20 rounded overflow-hidden flex flex-col items-center justify-center relative"
          style={{
            backgroundImage: resultUrl ? `repeating-conic-gradient(#1a1525 0% 25%, #2a2438 0% 50%)` : 'none',
            backgroundSize: '20px 20px'
          }}
        >
          {resultUrl ? (
            <img src={resultUrl} className="w-full h-full object-contain drop-shadow-2xl" alt="Extracted Asset" />
          ) : (
            <>
              {(status === 'queueing' || status === 'polling' || status === 'diffing') ? (
                <RefreshCw className="w-8 h-8 text-indigo-500 animate-spin" />
              ) : (
                <ImageIcon className="w-8 h-8 mb-2 opacity-20 text-indigo-500" />
              )}
            </>
          )}
          
          {error && (
            <div className="absolute inset-x-0 bottom-0 bg-red-900/80 p-2 flex items-start gap-2 border-t border-red-500/50">
              <AlertCircle className="w-4 h-4 text-red-200 shrink-0 mt-0.5" />
              <span className="text-[10px] text-red-100">{error}</span>
            </div>
          )}
        </div>
        
        <div className="flex gap-2 mt-2">
          <button 
            onClick={generateAsset}
            disabled={status !== 'idle' && status !== 'succeeded' && status !== 'failed'}
            className="nodrag flex-1 py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold rounded shadow-lg flex items-center justify-center gap-1 disabled:opacity-50 transition-all"
          >
            <Play className="w-3 h-3 fill-current" />
            GENERATE & EXTRACT
          </button>
          {resultUrl && (
            <button
              onClick={() => {
                const a = document.createElement('a');
                a.href = resultUrl;
                a.download = `asset-${id}.png`;
                a.target = '_blank';
                a.click();
              }}
              className="nodrag flex-1 py-2 bg-gray-700/80 hover:bg-gray-600 border border-gray-500/50 text-white text-xs font-bold rounded shadow-lg transition-colors flex items-center justify-center gap-1"
            >
              DOWNLOAD PNG
            </button>
          )}
        </div>
      </div>

      <Handle type="source" position={Position.Right} id="image" className="!w-4 !h-4 !bg-[#22c55e] !border-none !right-[-8px]" />
    </div>
  );
}

import { useState } from "react";
import { Handle, Position, useReactFlow } from "reactflow";
import { Eraser, Play, RefreshCw, AlertCircle, ImageIcon } from "lucide-react";
import { removeBackground as imglyRemoveBackground } from "@imgly/background-removal";

export default function BackgroundRemoverNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [status, setStatus] = useState<"idle" | "processing" | "succeeded" | "failed">("idle");
  const [resultUrl, setResultUrl] = useState<string | null>(data.resultUrl || null);
  const [error, setError] = useState<string | null>(null);

  const { getNodes, getEdges, setNodes } = useReactFlow();

  const removeBackground = async () => {
    // Gather Inputs
    const nodes = getNodes();
    const edges = getEdges();
    const incomingEdges = edges.filter(e => e.target === id);

    let inputImageUrl = "";

    incomingEdges.forEach(edge => {
      const sourceNode = nodes.find(n => n.id === edge.source);
      if (!sourceNode) return;
      if (edge.targetHandle === 'image') {
        inputImageUrl = sourceNode.data.imageUrl || sourceNode.data.resultUrl || sourceNode.data.image || "";
      }
    });

    if (!inputImageUrl) {
      setError("No input image connected.");
      setStatus("failed");
      return;
    }

    setStatus("processing");
    setError(null);

    try {
      // Create a blob from the input URL if it's not already
      const blobSource: Blob | string = inputImageUrl;

      const blob = await imglyRemoveBackground(blobSource, {
        progress: (key, current, total) => {
          // Could track progress here
          console.log(`Downloading model... ${key} - ${current}/${total}`);
        }
      });

      const reader = new FileReader();
      const base64Url: string = await new Promise((resolve) => {
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(blob);
      });

      const trimmedBase64: string = await new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement("canvas");
          canvas.width = img.width;
          canvas.height = img.height;
          const ctx = canvas.getContext("2d")!;
          ctx.drawImage(img, 0, 0);

          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const data = imageData.data;

          let minX = canvas.width, minY = canvas.height, maxX = 0, maxY = 0;
          let hasVisiblePixels = false;

          for (let y = 0; y < canvas.height; y++) {
            for (let x = 0; x < canvas.width; x++) {
              const alpha = data[(y * canvas.width + x) * 4 + 3];
              if (alpha > 10) {
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
                hasVisiblePixels = true;
              }
            }
          }

          if (!hasVisiblePixels) {
            resolve(base64Url);
            return;
          }

          const padding = 10;
          minX = Math.max(0, minX - padding);
          minY = Math.max(0, minY - padding);
          maxX = Math.min(canvas.width - 1, maxX + padding);
          maxY = Math.min(canvas.height - 1, maxY + padding);

          const width = maxX - minX + 1;
          const height = maxY - minY + 1;
          const trimmedCanvas = document.createElement("canvas");
          trimmedCanvas.width = width;
          trimmedCanvas.height = height;
          const tCtx = trimmedCanvas.getContext("2d")!;
          tCtx.putImageData(ctx.getImageData(minX, minY, width, height), 0, 0);
          resolve(trimmedCanvas.toDataURL("image/png"));
        };
        img.src = base64Url;
      });

      setResultUrl(trimmedBase64);
      setStatus("succeeded");

      setNodes(nds => nds.map(n => n.id === id ? { 
        ...n, 
        data: { ...n.data, resultUrl: trimmedBase64, imageUrl: trimmedBase64 } 
      } : n));

    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to remove background.");
      setStatus("failed");
    }
  };

  return (
    <div className={`w-72 bg-[#1a1525] rounded-lg shadow-2xl transition-all duration-200 relative ${
      selected ? "border-2 border-[#fbbf24]" : "border-2 border-indigo-500/30"
    }`}>
      <div className="bg-indigo-900/20 px-4 py-3 flex items-center justify-between border-b border-indigo-500/20 rounded-t-lg">
        <div className="flex items-center gap-2">
          <Eraser className="w-5 h-5 text-indigo-400" />
          <span className="font-bold text-xs text-indigo-100 uppercase tracking-wider">BG Remover</span>
        </div>
        {status !== 'idle' && (
          <div className="flex items-center gap-2">
            <span className="text-[10px] uppercase tracking-wider text-blue-400 font-bold animate-pulse">{status}</span>
          </div>
        )}
      </div>

      <div className="p-4 space-y-3">
        {/* Image Preview with checkerboard pattern to show transparency */}
        <div 
          className="w-full aspect-square border border-indigo-500/20 rounded overflow-hidden flex flex-col items-center justify-center relative"
          style={{
            backgroundImage: `repeating-conic-gradient(#1a1525 0% 25%, #2a2438 0% 50%)`,
            backgroundSize: '20px 20px'
          }}
        >
          {resultUrl ? (
            <img src={resultUrl} className="w-full h-full object-contain" alt="Background Removed" />
          ) : (
            <>
              {status === 'processing' ? (
                <RefreshCw className="w-8 h-8 text-indigo-500 animate-spin" />
              ) : (
                <ImageIcon className="w-8 h-8 opacity-20 text-indigo-500" />
              )}
            </>
          )}

          {error && (
            <div className="absolute inset-x-0 bottom-0 bg-red-900/80 p-2 flex items-start gap-2 border-t border-red-500/50">
              <AlertCircle className="w-4 h-4 text-red-200 shrink-0 mt-0.5" />
              <span className="text-[10px] text-red-100">{error}</span>
            </div>
          )}
        </div>

        <div className="flex gap-2">
          <button 
            onClick={removeBackground}
            disabled={status === 'processing'}
            className="nodrag flex-[2] py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-bold rounded shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-all"
          >
            <Play className="w-4 h-4 fill-current" />
            PROCESS
          </button>
          {resultUrl && (
            <button
              onClick={() => {
                const a = document.createElement('a');
                a.href = resultUrl;
                a.download = `bg-removed-${id}.png`;
                a.target = '_blank';
                a.click();
              }}
              className="nodrag flex-1 py-2 bg-gray-700/80 hover:bg-gray-600 border border-gray-500/50 text-white text-[10px] font-bold rounded shadow-lg transition-colors flex items-center justify-center gap-1"
            >
              DOWNLOAD
            </button>
          )}
        </div>
      </div>

      <Handle type="target" position={Position.Left} id="image" className="!w-4 !h-4 !bg-[#22c55e] !border-none !left-[-8px]" style={{ top: '50%' }} />
      <Handle type="source" position={Position.Right} id="image" className="!w-4 !h-4 !bg-[#22c55e] !border-none !right-[-8px]" style={{ top: '50%' }} />
    </div>
  );
}

import { useState, useEffect } from "react";
import { Handle, Position, useReactFlow } from "reactflow";
import { Sparkles, RefreshCw, ChevronDown, ChevronUp } from "lucide-react";
import { fetchNodePrompt, TEXT_MODELS } from "@/lib/plenxai";
import { GOOGLE_MODELS } from "@/lib/gemini";
import { generateTextUniversal } from "@/lib/llm-router";

export default function GeminiRefinerNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [isRefining, setIsRefining] = useState(false);
  const [refinedText, setRefinedText] = useState<string>(data.refinedText || "");
  const [isCollapsed, setIsCollapsed] = useState(true);
  const [selectedModel, setSelectedModel] = useState<string>(data.model || "gemini-2.5-flash");
  const [isModelMenuOpen, setIsModelMenuOpen] = useState(false);
  const [textProvider, setTextProvider] = useState<"plenxai" | "google">("plenxai");
  const { getNodes, getEdges, setNodes } = useReactFlow();

  useEffect(() => {
    setTextProvider((localStorage.getItem("artist-assistant-text-provider") as any) || "plenxai");
    const handleProviderChange = (e: any) => setTextProvider(e.detail);
    window.addEventListener("text-provider-changed", handleProviderChange);
    return () => window.removeEventListener("text-provider-changed", handleProviderChange);
  }, []);

  const activeModels = textProvider === "google" ? GOOGLE_MODELS : TEXT_MODELS;

  const handleRefine = async () => {
    // Gather inputs connected to this node
    const nodes = getNodes();
    const edges = getEdges();
    const incomingEdges = edges.filter(e => e.target === id);
    
    const promptParts: string[] = [];
    const imageRefs: string[] = [];
    
    incomingEdges.forEach(edge => {
      const sourceNode = nodes.find(n => n.id === edge.source);
      if (!sourceNode) return;
      
      if (edge.targetHandle === 'text') {
        const text = sourceNode.data.text || sourceNode.data.bakedStyle || "";
        if (text) promptParts.push(text);
      } else if (edge.targetHandle === 'image') {
        const image = sourceNode.data.imageUrl || sourceNode.data.image || sourceNode.data.referenceImage || sourceNode.data.bakedImage;
        if (image) imageRefs.push(image);
        if (sourceNode.data.images && Array.isArray(sourceNode.data.images)) {
          imageRefs.push(...sourceNode.data.images);
        }
      }
    });

    const rawPrompt = promptParts.join(", ");
    if (!rawPrompt) {
      alert("No input text found to refine.");
      return;
    }

    setIsRefining(true);
    try {
      let systemPrompt = await fetchNodePrompt('GeminiRefinerNode');
      if (!systemPrompt) systemPrompt = `You are a prompt engineer. Refine the user's raw idea into a high-quality, detailed prompt for AI image generation. Output ONLY the refined prompt text.\n\nUser Input:\n{prompt}`;
      
      const finalPrompt = systemPrompt.replace('{prompt}', rawPrompt);

      const response = await generateTextUniversal(finalPrompt, imageRefs.length > 0 ? imageRefs : undefined, selectedModel);
      if (response.success && response.text) {
        setRefinedText(response.text);
        setNodes(nds => nds.map(n => n.id === id ? { 
          ...n, 
          data: { ...n.data, refinedText: response.text } 
        } : n));
      } else {
        alert("Refinement failed: " + (response.error || (response as any).message || JSON.stringify(response)));
      }
    } catch (error) {
      alert("Error calling Gemini API.");
    } finally {
      setIsRefining(false);
    }
  };

  return (
    <div className={`w-72 bg-[#1a1525] rounded-lg shadow-[0_0_15px_rgba(168,85,247,0.2)] transition-all duration-200 ${
      selected 
        ? "outline outline-5 outline-[#fbbf24] shadow-[0_0_25px_rgba(251,191,36,0.6)] border-transparent" 
        : "border-2 border-emerald-500/50"
    }`}>
      <div className="bg-emerald-900/40 px-4 py-3 flex items-center justify-between border-b border-emerald-500/30 rounded-t-lg">
        <div className="flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-emerald-400" />
          <span className="font-bold text-xs text-emerald-100 uppercase tracking-wider">Gemini Refiner</span>
        </div>
        {isRefining && <RefreshCw className="w-4 h-4 text-emerald-400 animate-spin" />}
      </div>

      <div className="p-4 space-y-3">
        <div className="relative group">
          <div className={`min-h-[80px] bg-black/40 border border-emerald-500/20 rounded p-2 text-xs text-emerald-100/70 italic ${isCollapsed ? "max-h-24 overflow-hidden" : ""}`}>
            {refinedText || "Connect Prompt/Style nodes and click Refine to polish your prompt..."}
          </div>
          {refinedText && refinedText.length > 150 && (
            <button 
              onClick={() => setIsCollapsed(!isCollapsed)}
              className="absolute top-1 right-1 text-emerald-400 hover:text-emerald-300 transition-colors bg-[#1a1525]/80 p-0.5 rounded shadow-sm"
            >
              {isCollapsed ? <ChevronDown className="w-4 h-4" /> : <ChevronUp className="w-4 h-4" />}
            </button>
          )}
        </div>

        <div className="relative z-20">
          <label className="text-[10px] uppercase tracking-wider text-emerald-400/60 font-bold mb-1 block">Generative Model</label>
          <button 
            onClick={() => setIsModelMenuOpen(!isModelMenuOpen)}
            className="nodrag w-full bg-black/40 border border-emerald-500/20 rounded px-3 py-2 flex items-center justify-between hover:border-emerald-500/40 transition-colors"
          >
            <span className="text-xs text-emerald-100 font-medium">
              {activeModels.find(m => m.id === selectedModel)?.name || "Select Model"}
            </span>
            <ChevronDown className={`w-4 h-4 text-emerald-400 transition-transform ${isModelMenuOpen ? 'rotate-180' : ''}`} />
          </button>
          
          {isModelMenuOpen && (
            <div className="absolute top-full left-0 right-0 mt-1 bg-[#1a2230] border border-emerald-500/30 rounded shadow-2xl overflow-hidden animate-in fade-in z-30">
              {activeModels.map((m) => (
                <button
                  key={m.id}
                  onClick={() => {
                    setSelectedModel(m.id);
                    setIsModelMenuOpen(false);
                    setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, model: m.id } } : n));
                  }}
                  className={`w-full px-3 py-2 text-left text-xs transition-colors hover:bg-emerald-600/20 ${
                    selectedModel === m.id ? 'text-emerald-400 font-bold bg-emerald-600/10' : 'text-emerald-100/70'
                  }`}
                >
                  {m.name}
                </button>
              ))}
            </div>
          )}
        </div>

        <button 
          onClick={handleRefine}
          disabled={isRefining}
          className="nodrag w-full py-2 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold rounded shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-all"
        >
          {isRefining ? "Polishing..." : "REFINE PROMPT"}
        </button>

        <div className="flex flex-col gap-1 pt-2 border-t border-emerald-500/20">
          <div className="relative flex items-center h-6">
            <Handle
              type="target"
              id="text"
              position={Position.Left}
              className="!w-4 !h-4 !bg-[#3b82f6] !border-none !min-w-0 !min-h-0 !left-[-24px]"
            />
            <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Prompt Input</span>
          </div>
          <div className="relative flex items-center h-6">
            <Handle
              type="target"
              id="image"
              position={Position.Left}
              className="!w-4 !h-4 !bg-[#22c55e] !border-none !min-w-0 !min-h-0 !left-[-24px]"
            />
            <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Reference Image</span>
          </div>
        </div>
      </div>

      {/* Output */}
      <Handle
        type="source"
        position={Position.Right}
        id="text"
        className="!w-4 !h-4 !bg-[#3b82f6] !border-none !min-w-0 !min-h-0"
      />
    </div>
  );
}

import { useState, useEffect } from "react";
import { Handle, Position, useReactFlow, useNodes, useEdges } from "reactflow";
import { Search, RefreshCw, Image as ImageIcon, Eye, EyeOff, ChevronDown, ChevronUp } from "lucide-react";
import { TEXT_MODELS } from "@/lib/plenxai";
import { GOOGLE_MODELS } from "@/lib/gemini";
import { explainImageUniversal } from "@/lib/llm-router";

export default function ImageExplainedNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [isExplaining, setIsExplaining] = useState(false);
  const [explainedText, setExplainedText] = useState<string>(data.explainedText || "");
  const [showRawRequest, setShowRawRequest] = useState(false);
  const [isCollapsed, setIsCollapsed] = useState(true);
  const [selectedModel, setSelectedModel] = useState<string>(data.model || "gemini-2.5-flash");
  const [isModelMenuOpen, setIsModelMenuOpen] = useState(false);
  const [textProvider, setTextProvider] = useState<"plenxai" | "google">("plenxai");

  const { setNodes } = useReactFlow();

  useEffect(() => {
    setTextProvider((localStorage.getItem("artist-assistant-text-provider") as any) || "plenxai");
    const handleProviderChange = (e: any) => setTextProvider(e.detail);
    window.addEventListener("text-provider-changed", handleProviderChange);
    return () => window.removeEventListener("text-provider-changed", handleProviderChange);
  }, []);

  const activeModels = textProvider === "google" ? GOOGLE_MODELS : TEXT_MODELS;
  const nodes = useNodes();
  const allEdges = useEdges();

  const handles: string[] = data.imageInputs || ["image-0"];
  const everConnected: Record<string, boolean> = data.everConnected || {};

  // 1. Tracking "Ever Connected" status for handles
  useEffect(() => {
    const connectedHandleIds = allEdges
      .filter(e => e.target === id && e.targetHandle !== "image-plus")
      .map(e => e.targetHandle);

    let changed = false;
    const nextEver = { ...everConnected };
    connectedHandleIds.forEach(h => {
      if (h && !nextEver[h]) {
        nextEver[h] = true;
        changed = true;
      }
    });

    if (changed) {
      setNodes(nds => nds.map(n => n.id === id ? { 
        ...n, 
        data: { ...n.data, everConnected: nextEver } 
      } : n));
    }
  }, [allEdges, id, everConnected, setNodes]);

  // 2. Handle Auto-Deletion
  useEffect(() => {
    const edges = allEdges.filter(e => e.target === id);
    const connectedHandleIds = edges.map(e => e.targetHandle);

    const nextHandles = handles.filter(h => {
      const isConnected = connectedHandleIds.includes(h);
      const isInitial = h === "image-0";
      const hasBeenUsed = everConnected[h];

      if (isConnected) return true;
      if (isInitial && !hasBeenUsed) return true;
      return false;
    });

    if (nextHandles.length !== handles.length) {
      setNodes(nds => nds.map(n => n.id === id ? { 
        ...n, 
        data: { ...n.data, imageInputs: nextHandles } 
      } : n));
    }
  }, [allEdges, id, handles, everConnected, setNodes]);

  const getFragmentImage = (handleId: string) => {
    const edge = allEdges.find(e => e.target === id && e.targetHandle === handleId);
    if (!edge) return null;
    const node = nodes.find(n => n.id === edge.source) as any;
    if (!node) return null;
    return node.data.image || node.data.referenceImage || node.data.bakedImage || node.data.imageUrl || null;
  };

  const activeImages = handles.map(h => getFragmentImage(h)).filter(img => img);

  const generatedPrompt = `Describe what is going on in these ${Math.max(1, activeImages.length)} image(s) in detail. Focus on composition, character/object detail, and storytelling should any of these elements be present in the image. You must write approximately 1000 characters for each image.`;

  const handleExplain = async () => {
    if (activeImages.length === 0) return;

    setIsExplaining(true);
    try {
      const response = await explainImageUniversal(activeImages, generatedPrompt, selectedModel);
      if (response.success && response.text) {
        setExplainedText(response.text);
        setNodes(nds => nds.map(n => n.id === id ? { 
          ...n, 
          data: { ...n.data, text: response.text, explainedText: response.text } 
        } : n));
      } else {
        alert("Explanation failed: " + (response.error || (response as any).message || JSON.stringify(response)));
      }
    } catch (error) {
      alert("Error calling Gemini API.");
    } finally {
      setIsExplaining(false);
    }
  };

  return (
    <div className={`w-80 bg-[#1a1525] rounded-lg shadow-[0_0_15px_rgba(16,185,129,0.2)] transition-all duration-200 relative ${
      selected 
        ? "outline outline-5 outline-[#fbbf24] shadow-[0_0_25px_rgba(251,191,36,0.6)] border-transparent" 
        : "border-2 border-emerald-500/50"
    }`}>
      <div className="bg-emerald-900/40 px-3 py-2 flex items-center justify-between border-b border-emerald-500/30 rounded-t-lg">
        <div className="flex items-center gap-2">
          <Search className="w-5 h-5 text-emerald-400" />
          <span className="font-bold text-xs text-emerald-100 uppercase tracking-wider">Image Analyzer</span>
        </div>
        {isExplaining && <RefreshCw className="w-4 h-4 text-emerald-400 animate-spin" />}
      </div>

      <div className="p-3 space-y-4">
        {/* Dynamic Handle Slots */}
        {handles.map((hId, idx) => {
          const fragImg = getFragmentImage(hId);
          const isConnected = fragImg !== null;

          return (
            <div key={hId} className="relative group/slot">
              {/* Receiver Handle */}
              <Handle
                type="target"
                position={Position.Left}
                id={hId}
                className={`!w-4 !h-4 !bg-[#22c55e] !border-none !min-w-0 !min-h-0 !left-[-22px] transition-all duration-200 ${
                  isConnected ? "!scale-110" : ""
                }`}
                style={{ top: "50%", transform: "translateY(-50%)" }}
                title={`Image Input ${hId}`}
              />

              {isConnected ? (
                <div className="flex items-center justify-between px-3 py-2.5 rounded-lg border bg-emerald-500/10 border-emerald-500/30 shadow-sm text-emerald-200">
                  <div className="flex items-center gap-2 opacity-80">
                    <ImageIcon className="w-4 h-4" />
                    <span className="text-xs font-medium">Linked Image</span>
                  </div>
                  <div className="w-8 h-8 rounded bg-black/40 border border-emerald-500/20 overflow-hidden flex items-center justify-center">
                    {/* Tiny thumbnail preview if it's base64 or URL */}
                    {fragImg && typeof fragImg === 'string' && (fragImg.startsWith('data:') || fragImg.startsWith('http')) ? (
                      <img src={fragImg} alt="preview" className="max-w-full max-h-full object-contain" />
                    ) : (
                      <ImageIcon className="w-full h-full p-2 opacity-30" />
                    )}
                  </div>
                </div>
              ) : (
                <div className="h-10 w-full bg-[#141b22] rounded-xl border border-emerald-500/10 shadow-inner flex items-center px-3">
                  <span className="text-xs text-emerald-100/30 italic">Connect an image...</span>
                </div>
              )}
            </div>
          );
        })}

        {/* The "+" Spawner Handle */}
        <div className="relative flex items-center h-6 mt-2 mb-2">
          <Handle
            type="target"
            position={Position.Left}
            id="image-plus"
            className="!w-5 !h-5 !bg-[#22c55e] !border-none !flex !items-center !justify-center !min-w-0 !min-h-0 !left-[-24px] cursor-crosshair hover:scale-110 transition-transform shadow-md"
            title="Drop wire here to add a new image input"
          >
            <span className="text-[#1a1525] font-black text-lg leading-none mt-[-2px] ml-[1px]">+</span>
          </Handle>
          <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Add Image</span>
        </div>

        {/* Model Selection */}
        <div className="relative z-20 mb-2">
          <label className="text-[10px] uppercase tracking-wider text-emerald-400/60 font-bold mb-1 block">Generative Model</label>
          <button 
            onClick={() => setIsModelMenuOpen(!isModelMenuOpen)}
            className="nodrag w-full bg-black/40 border border-emerald-500/20 rounded px-3 py-2 flex items-center justify-between hover:border-emerald-500/40 transition-colors"
          >
            <span className="text-xs text-emerald-100 font-medium">
              {activeModels.find(m => m.id === selectedModel)?.name || "Select Model"}
            </span>
            <ChevronDown className={`w-4 h-4 text-emerald-400 transition-transform ${isModelMenuOpen ? 'rotate-180' : ''}`} />
          </button>

          {isModelMenuOpen && (
            <div className="absolute top-full left-0 right-0 mt-1 bg-[#1a2230] border border-emerald-500/30 rounded shadow-2xl overflow-hidden animate-in fade-in z-30">
              {activeModels.map((m) => (
                <button
                  key={m.id}
                  onClick={() => {
                    setSelectedModel(m.id);
                    setIsModelMenuOpen(false);
                    setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, model: m.id } } : n));
                  }}
                  className={`w-full px-3 py-2 text-left text-xs transition-colors hover:bg-emerald-600/20 ${
                    selectedModel === m.id ? 'text-emerald-400 font-bold bg-emerald-600/10' : 'text-emerald-100/70'
                  }`}
                >
                  {m.name}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Raw Request Toggle */}
        <div className="flex justify-end">
          <button 
            onClick={() => setShowRawRequest(!showRawRequest)}
            className="text-[10px] text-emerald-400/70 hover:text-emerald-300 flex items-center gap-1 transition-colors"
          >
            {showRawRequest ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
            {showRawRequest ? "Hide API Prompt" : "Show API Prompt"}
          </button>
        </div>

        {showRawRequest && (
          <div className="bg-black/60 border border-emerald-500/30 rounded p-2 text-[10px] text-emerald-100/80 font-mono overflow-auto max-h-32">
            <div className="mb-1 text-emerald-400 font-bold">Prompt to PlenxAI:</div>
            {generatedPrompt}
            <div className="mt-1 text-emerald-400/50">Number of images: {activeImages.length}</div>
          </div>
        )}

        <div className="relative group">
          <div className={`min-h-[80px] bg-black/40 border border-emerald-500/20 rounded p-2 text-xs text-emerald-100/70 italic whitespace-pre-wrap ${isCollapsed ? "max-h-32 overflow-hidden" : ""}`}>
            {explainedText || "Click Explain to analyze the images..."}
          </div>
          {explainedText && explainedText.length > 200 && (
            <button 
              onClick={() => setIsCollapsed(!isCollapsed)}
              className="absolute top-1 right-1 text-emerald-400 hover:text-emerald-300 transition-colors bg-[#1a1525]/80 p-0.5 rounded shadow-sm"
            >
              {isCollapsed ? <ChevronDown className="w-4 h-4" /> : <ChevronUp className="w-4 h-4" />}
            </button>
          )}
        </div>

        <button 
          onClick={handleExplain}
          disabled={isExplaining}
          className="nodrag w-full py-2 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold rounded shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-all"
        >
          {isExplaining ? "Analyzing..." : "EXPLAIN IMAGE"}
        </button>
      </div>

      {/* Output - Text */}
      <Handle
        type="source"
        position={Position.Right}
        id="text"
        className="!w-4 !h-4 !bg-[#3b82f6] !border-none !min-w-0 !min-h-0"
      />
    </div>
  );
}

import { useState } from "react";
import { Handle, Position, useReactFlow, useEdges } from "reactflow";
import { Scissors, Download, Loader2 } from "lucide-react";

export default function IsometricHexSlicerNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [slices, setSlices] = useState<{name: string, url: string}[]>(data.slices || []);
  const [isProcessing, setIsProcessing] = useState(false);
  const [useWallCloning, setUseWallCloning] = useState(data.useWallCloning !== undefined ? data.useWallCloning : true);

  const { getNodes, setNodes } = useReactFlow();
  const allEdges = useEdges();

  const incomingEdges = allEdges.filter(e => e.target === id && e.targetHandle === 'image');

  const processImage = async () => {
    if (incomingEdges.length === 0) return setSlices([]);
    const sourceNode = getNodes().find(n => n.id === incomingEdges[0].source);
    const imageUrl = sourceNode?.data?.resultUrl || sourceNode?.data?.imageUrl;
    if (!imageUrl) return;

    setIsProcessing(true);

    try {
      const guideImg = new Image();
      guideImg.crossOrigin = "anonymous";
      guideImg.src = "/assets/hex-tool/1x1_Island_ColorGuide.png";

      const sourceImg = new Image();
      sourceImg.crossOrigin = "anonymous";
      sourceImg.src = imageUrl;

      await Promise.all([
        new Promise(res => guideImg.onload = res),
        new Promise(res => sourceImg.onload = res)
      ]);

      const targetW = 1212;
      const targetH = 1212;

      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) throw new Error("No 2d context");
      canvas.width = targetW;
      canvas.height = targetH;

      const targetAspect = targetW / targetH;
      const sourceAspect = sourceImg.width / sourceImg.height;

      let cropX = 0, cropY = 0, cropW = sourceImg.width, cropH = sourceImg.height;

      if (Math.abs(sourceAspect - targetAspect) > 0.01) {
        if (sourceAspect < targetAspect) {
          cropW = sourceImg.width;
          cropH = sourceImg.width / targetAspect;
          cropY = (sourceImg.height - cropH) / 2;
        } else {
          cropH = sourceImg.height;
          cropW = sourceImg.height * targetAspect;
          cropX = (sourceImg.width - cropW) / 2;
        }
      }

      ctx.drawImage(sourceImg, cropX, cropY, cropW, cropH, 0, 0, targetW, targetH);
      const sourceData = ctx.getImageData(0, 0, targetW, targetH).data;

      const guideCanvas = document.createElement('canvas');
      guideCanvas.width = targetW;
      guideCanvas.height = targetH;
      const guideCtx = guideCanvas.getContext('2d', { willReadFrequently: true });
      guideCtx?.drawImage(guideImg, 0, 0, targetW, targetH);
      const guideData = guideCtx?.getImageData(0, 0, targetW, targetH).data;

      if (!guideData) throw new Error("Could not read guide data");

      // Find Darkest Color
      let darkestColor = { r: 0, g: 0, b: 0 };
      let minLuma = 255;
      for (let i = 0; i < sourceData.length; i += 4) {
        if (sourceData[i+3] > 128) {
          const luma = (sourceData[i] + sourceData[i+1] + sourceData[i+2]) / 3;
          if (luma < minLuma && luma > 5) {
            minLuma = luma;
            darkestColor = { r: sourceData[i], g: sourceData[i+1], b: sourceData[i+2] };
          }
        }
      }

      const palette = [
        { name: 'Background', r: 0, g: 0, b: 0, ignore: true },
        { name: 'Gray', r: 63, g: 63, b: 63, ignore: true },
        { name: 'TopFace', r: 255, g: 255, b: 0, isCube: true },
        { name: 'LeftSideFace', r: 0, g: 255, b: 128, isCube: true },
        { name: 'RightSideFace', r: 255, g: 0, b: 255, isCube: true },
        { name: 'CenterFill', r: 128, g: 0, b: 255, island: true, immune: [] },
        { name: 'OutterCornerNorth', r: 255, g: 255, b: 0, island: true, immune: ['top'] },
        { name: 'OutterCornerWest', r: 0, g: 0, b: 255, island: true, immune: ['top', 'left'] },
        { name: 'OutterCornerEast', r: 0, g: 255, b: 0, island: true, immune: ['top', 'right'] },
        { name: 'OutterCornerSouth', r: 255, g: 0, b: 0, island: true, immune: ['top', 'left', 'right'] },
        { name: 'InnerCornerNorth', r: 0, g: 128, b: 255, island: true, immune: [] },
        { name: 'InnerCornerWest', r: 128, g: 255, b: 0, island: true, immune: [] },
        { name: 'InnerCornerEast', r: 255, g: 0, b: 128, island: true, immune: [] },
        { name: 'InnerCornerSouth', r: 255, g: 191, b: 0, island: true, immune: [] },
        { name: 'EdgeNorthWest', r: 255, g: 0, b: 255, island: true, immune: ['top'] },
        { name: 'EdgeNorthEast', r: 0, g: 255, b: 255, island: true, immune: ['top'] },
        { name: 'EdgeSouthWest', r: 0, g: 255, b: 128, island: true, immune: ['left'] },
        { name: 'EdgeSouthEast', r: 255, g: 128, b: 0, island: true, immune: ['right'] }
      ];

      const getNearest = (r: number, g: number, b: number, x: number, y: number) => {
        let bestDist = Infinity;
        let bestEntry = palette[0];
        for (const p of palette) {
          if (p.isCube && y < 800) continue;
          if (p.island && y >= 800) continue;
          const dist = (p.r - r)**2 + (p.g - g)**2 + (p.b - b)**2;
          if (dist < bestDist) {
            bestDist = dist;
            bestEntry = p;
          }
        }
        return bestEntry;
      };

      const extracted: Record<string, { bounds: {minX:number, maxX:number, minY:number, maxY:number}, data: ImageData }> = {};

      for (const p of palette) {
        if (!p.ignore) {
          extracted[p.name] = {
            bounds: { minX: targetW, maxX: 0, minY: targetH, maxY: 0 },
            data: new ImageData(targetW, targetH)
          };
        }
      }

      for (let y = 0; y < targetH; y++) {
        for (let x = 0; x < targetW; x++) {
          const i = (y * targetW + x) * 4;
          if (guideData[i+3] > 128) {
            const nearest = getNearest(guideData[i], guideData[i+1], guideData[i+2], x, y);
            if (!nearest.ignore) {
              const entry = extracted[nearest.name];
              const r = sourceData[i];
              const g = sourceData[i+1];
              const b = sourceData[i+2];

              // Chroma-key out black background fringes
              const isBlack = (r < 15 && g < 15 && b < 15);

              entry.data.data[i] = r;
              entry.data.data[i+1] = g;
              entry.data.data[i+2] = b;
              entry.data.data[i+3] = isBlack ? 0 : 255;
              if (x < entry.bounds.minX) entry.bounds.minX = x;
              if (x > entry.bounds.maxX) entry.bounds.maxX = x;
              if (y < entry.bounds.minY) entry.bounds.minY = y;
              if (y > entry.bounds.maxY) entry.bounds.maxY = y;
            }
          }
        }
      }

      const cubeOffsetX = 466;
      const cubeOffsetY = 851;

      const logicalOffsets: Record<string, {x: number, y: number}> = {
        'CenterFill': {x: 466, y: 332},
        'InnerCornerNorth': {x: 466, y: 192},
        'InnerCornerSouth': {x: 466, y: 472},
        'InnerCornerWest': {x: 186, y: 332},
        'InnerCornerEast': {x: 746, y: 332},
        'EdgeNorthWest': {x: 186, y: 192},
        'EdgeNorthEast': {x: 746, y: 192},
        'EdgeSouthWest': {x: 186, y: 472},
        'EdgeSouthEast': {x: 746, y: 472},
        'OutterCornerWest': {x: 46, y: 402},
        'OutterCornerEast': {x: 886, y: 402},
        'OutterCornerSouth': {x: 606, y: 542},
        'OutterCornerNorth': {x: 326, y: 122}
      };

      const hexPath = new Path2D();
      hexPath.moveTo(140, 0);
      hexPath.lineTo(280, 70);
      hexPath.lineTo(280, 210);
      hexPath.lineTo(140, 280);
      hexPath.lineTo(0, 210);
      hexPath.lineTo(0, 70);
      hexPath.closePath();

      const newSlices: {name: string, url: string}[] = [];

      for (const p of palette) {
        if (!p.island) continue;
        const outCanvas = document.createElement('canvas');
        outCanvas.width = 280;
        outCanvas.height = 280;
        const oCtx = outCanvas.getContext('2d');
        if (!oCtx) continue;

        // Hexagon background is now truly transparent, not filled with darkestColor!

        const chunk = extracted[p.name];
        const offset = logicalOffsets[p.name];
        if (!offset) continue; // safety check

        const tileOffsetX = offset.x;
        const tileOffsetY = offset.y;

        // Temp canvas to hold raw ImageData
        const tempC = document.createElement('canvas');
        tempC.width = targetW;
        tempC.height = targetH;
        const tempCtx = tempC.getContext('2d')!;

        // 2. Draw non-immune Cube Faces (either cloned pixels or darkestColor fill)
        ['TopFace', 'LeftSideFace', 'RightSideFace'].forEach(face => {
          const isTop = face === 'TopFace';
          const isLeft = face === 'LeftSideFace';
          const isRight = face === 'RightSideFace';
          if ((isTop && !p.immune?.includes('top')) ||
              (isLeft && !p.immune?.includes('left')) ||
              (isRight && !p.immune?.includes('right'))) {

            const faceChunk = extracted[face];
            tempCtx.putImageData(faceChunk.data, 0, 0);

            if (useWallCloning) {
              oCtx.drawImage(
                tempC,
                cubeOffsetX, cubeOffsetY, 280, 280,
                0, 0, 280, 280
              );
            } else {
              // Fill obscured face with darkestColor
              const maskC = document.createElement('canvas');
              maskC.width = 280; maskC.height = 280;
              const mCtx = maskC.getContext('2d')!;
              mCtx.drawImage(tempC, cubeOffsetX, cubeOffsetY, 280, 280, 0, 0, 280, 280);
              mCtx.globalCompositeOperation = 'source-in';
              mCtx.fillStyle = `rgb(${darkestColor.r}, ${darkestColor.g}, ${darkestColor.b})`;
              mCtx.fillRect(0, 0, 280, 280);
              oCtx.drawImage(maskC, 0, 0);
            }
            tempCtx.clearRect(0, 0, targetW, targetH);
          }
        });

        // 3. Draw Island Chunk aligned by its top-left logical coordinate
        tempCtx.putImageData(chunk.data, 0, 0);
        oCtx.drawImage(
          tempC,
          tileOffsetX, tileOffsetY, 280, 280,
          0, 0, 280, 280
        );

        // 4. Clip to Hexagon
        oCtx.globalCompositeOperation = 'destination-in';
        oCtx.fill(hexPath);
        oCtx.globalCompositeOperation = 'source-over';

        // 5. Smear (Edge Padding) to fix anti-aliasing seams in Unity
        const imgData = oCtx.getImageData(0, 0, 280, 280);
        let currentData = imgData.data;
        for (let pass = 0; pass < 2; pass++) {
            const nextData = new Uint8ClampedArray(currentData);
            for (let y = 0; y < 280; y++) {
              for (let x = 0; x < 280; x++) {
                const i = (y * 280 + x) * 4;
                if (currentData[i+3] < 255) {
                  let found = false;
                  for (let dy = -1; dy <= 1; dy++) {
                    for (let dx = -1; dx <= 1; dx++) {
                      if (dx === 0 && dy === 0) continue;
                      const nx = x + dx;
                      const ny = y + dy;
                      if (nx >= 0 && nx < 280 && ny >= 0 && ny < 280) {
                        const ni = (ny * 280 + nx) * 4;
                        if (currentData[ni+3] === 255) {
                          nextData[i] = currentData[ni];
                          nextData[i+1] = currentData[ni+1];
                          nextData[i+2] = currentData[ni+2];
                          nextData[i+3] = 255;
                          found = true;
                          break;
                        }
                      }
                    }
                    if (found) break;
                  }
                }
              }
            }
            currentData = nextData;
        }
        oCtx.putImageData(new ImageData(currentData, 280, 280), 0, 0);

        newSlices.push({ name: p.name, url: outCanvas.toDataURL('image/png') });
      }

      setSlices(newSlices);
      setNodes(nds => nds.map(n => n.id === id ? { 
        ...n, 
        data: { ...n.data, slices: newSlices, sourceImageUrl: imageUrl, useWallCloning } 
      } : n));
    } catch (err) {
      console.error("Slicing failed", err);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className={`w-96 bg-[#1a1525] rounded-lg shadow-2xl transition-all duration-200 relative ${
      selected ? "border-2 border-[#fbbf24]" : "border-2 border-emerald-500/30"
    }`}>
      <div className="bg-emerald-900/20 px-4 py-3 flex items-center justify-between border-b border-emerald-500/20 rounded-t-lg">
        <div className="flex items-center gap-2">
          <Scissors className="w-5 h-5 text-emerald-400" />
          <span className="font-bold text-xs text-emerald-100 uppercase tracking-wider">V2 Token Slicer</span>
        </div>
        {isProcessing && <Loader2 className="w-4 h-4 text-emerald-400 animate-spin" />}
      </div>

      <div className="p-4 space-y-3">
        <div className="bg-black/30 p-4 border border-emerald-500/20 rounded min-h-[240px] flex items-center justify-center">
          {slices.length > 0 ? (
            <div className="grid grid-cols-4 gap-2 w-full max-h-96 overflow-y-auto pr-1 custom-scrollbar">
              {slices.map((slice, idx) => (
                <div key={idx} className="flex flex-col items-center gap-1 group">
                  <a 
                    href={slice.url}
                    download={`Tile_${slice.name}.png`}
                    className="aspect-square w-full border border-emerald-500/30 rounded overflow-hidden bg-black/50 hover:border-emerald-400 hover:scale-105 transition-all cursor-pointer relative block" 
                    title={`Download ${slice.name}`}
                  >
                    <img src={slice.url} className="w-full h-full object-contain" alt={slice.name} />
                    <div className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                      <Download className="w-4 h-4 text-emerald-400" />
                    </div>
                  </a>
                  <span className="text-[8px] text-emerald-200/60 truncate w-full text-center">{slice.name}</span>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center">
              <Scissors className="w-10 h-10 text-emerald-500/20 mx-auto mb-2" />
              <p className="text-xs text-emerald-200/40">Connect an image, then click SLICE</p>
            </div>
          )}
        </div>

        <div className="flex items-center justify-between bg-black/30 p-2.5 rounded border border-emerald-500/20">
          <label className="text-xs text-emerald-200/80 font-medium cursor-pointer select-none" onClick={() => setUseWallCloning(!useWallCloning)}>
            Clone Cube Faces
          </label>
          <button 
            onClick={() => setUseWallCloning(!useWallCloning)}
            className={`w-8 h-4 rounded-full transition-colors relative ${useWallCloning ? 'bg-emerald-500' : 'bg-gray-600'}`}
          >
            <div className={`w-3 h-3 bg-white rounded-full absolute top-0.5 transition-all`} style={{ left: useWallCloning ? '18px' : '2px' }} />
          </button>
        </div>

        <button 
          onClick={processImage}
          disabled={isProcessing}
          className="nodrag w-full py-2 bg-emerald-600 hover:bg-emerald-500 text-white text-sm font-bold rounded shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-all"
        >
          <Scissors className="w-4 h-4 fill-current" />
          SLICE 13 TILES
        </button>

        <div className="relative flex items-center h-6 mt-2">
          <Handle type="target" position={Position.Left} id="image" className="!w-4 !h-4 !bg-[#22c55e] !border-none !left-[-24px]" />
          <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Tileset Image Input</span>
        </div>
      </div>

      <Handle type="source" position={Position.Right} id="image-out" className="!w-4 !h-4 !bg-[#22c55e] !border-none !right-[-8px]" />
    </div>
  );
}

import { useState, useCallback, useEffect } from "react";
import { Handle, Position, useReactFlow, useUpdateNodeInternals, useEdges } from "reactflow";
import { ImageDown, RefreshCw, Play, AlertCircle, Download, Plus, ChevronDown } from "lucide-react";
import { queueImageGen, getTaskStatus, uploadMediaDirect } from "@/lib/plenxai";

const MODELS = [
  { id: "nano-banana-pro", name: "Nano Banana PRO" },
  { id: "nano-banana-full", name: "Nano Banana Full" },
  { id: "nano-banana-2", name: "Nano Banana 2" },
  { id: "kling-o1-image", name: "Kling O1 Image" },
  { id: "flux-2-pro", name: "Flux 2 Pro" },
  { id: "seedream-5-lite", name: "Seedream 5 Lite" },
  { id: "seedream-4-5", name: "Seedream 4.5" },
  { id: "grok-image", name: "Grok Image" },
  { id: "gpt-image-2", name: "GPT Image 2" }
];

export default function PlenxAIOutputNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [status, setStatus] = useState<"idle" | "queueing" | "polling" | "succeeded" | "failed">("idle");
  const [resultUrl, setResultUrl] = useState<string | null>(data.resultUrl || null);
  const [error, setError] = useState<string | null>(null);
  const [lastRunHash, setLastRunHash] = useState<string>(data.lastRunHash || "");
  const [selectedModel, setSelectedModel] = useState<string>(data.model || MODELS[0].id);
  const [isModelMenuOpen, setIsModelMenuOpen] = useState(false);
  const imageInputs: string[] = data.imageInputs || ["image-0"];

  const { getNodes, getEdges, setNodes } = useReactFlow();
  const allEdges = useEdges();
  const updateNodeInternals = useUpdateNodeInternals();

  // Notify React Flow to recalculate handle positions whenever the number of handles changes
  useEffect(() => {
    updateNodeInternals(id);
  }, [imageInputs.length, id, updateNodeInternals]);

  // Auto-cleanup disconnected image handles
  useEffect(() => {
    const connectedHandles = allEdges
      .filter(e => e.target === id)
      .map(e => e.targetHandle);

    const nextInputs = imageInputs.filter(h => {
      // Keep if it's connected
      if (connectedHandles.includes(h)) return true;
      // Keep the initial handle if nothing is connected to it to provide an empty slot
      if (h === "image-0" && !connectedHandles.includes(h)) return true;
      return false;
    });

    if (nextInputs.length !== imageInputs.length) {
      setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, imageInputs: nextInputs } } : n));
    }
  }, [allEdges, id, imageInputs, setNodes]);

  const generateImage = async () => {
    // 1. Gather Inputs
    const nodes = getNodes();
    const edges = getEdges();

    // Find all nodes connected to our input handles
    const incomingEdges = edges.filter(e => e.target === id);

    const promptParts: string[] = [];
    const imageRefs: string[] = [];

    incomingEdges.forEach(edge => {
      const sourceNode = nodes.find(n => n.id === edge.source);
      if (!sourceNode) return;

      if (edge.targetHandle === 'text') {
        const text = sourceNode.data.refinedText || sourceNode.data.text || sourceNode.data.bakedStyle || "";
        if (text) promptParts.push(text);
      } else if (edge.targetHandle?.startsWith('image-') || edge.targetHandle?.startsWith('img-')) {
        const image = sourceNode.data.imageUrl || sourceNode.data.image || sourceNode.data.referenceImage || sourceNode.data.bakedImage;
        if (image) imageRefs.push(image);
        // Also handle StyleInsertNode or bulk images if connected to an image handle
        if (sourceNode.data.images && Array.isArray(sourceNode.data.images)) {
          imageRefs.push(...sourceNode.data.images);
        }
      }
    });

    const finalPrompt = promptParts.join(", ");
    const currentHash = JSON.stringify({ prompt: finalPrompt, images: imageRefs, model: selectedModel });

    // 2. Change Detection
    if (status === 'succeeded' && currentHash === lastRunHash && resultUrl) {
      console.log("No changes detected, skipping API call.");
      return;
    }

    // 3. API Call
    const apiKey = localStorage.getItem("artist-assistant-image-api");
    if (!apiKey) {
      setError("Please enter PlenxAI API Key in Settings.");
      setStatus("failed");
      return;
    }

    if (!finalPrompt) {
      setError("No prompt detected. Connect a Prompt or Style node.");
      setStatus("failed");
      return;
    }

    setStatus("queueing");
    setError(null);

    const base64Images = imageRefs.filter(img => img.startsWith('data:image'));
    const urlImages = [...imageRefs.filter(img => !img.startsWith('data:image'))];

    try {
      // Upload base64 images first
      if (base64Images.length > 0) {
        console.log(`Uploading ${base64Images.length} base64 images to PlenxAI...`);
        for (const base64 of base64Images) {
          try {
            const uploadRes = await uploadMediaDirect(apiKey, base64);
            if (uploadRes.success && (uploadRes.url || uploadRes.cdn_url)) {
              urlImages.push(uploadRes.url || uploadRes.cdn_url);
            } else {
              console.warn("Image upload failed:", uploadRes.error);
            }
          } catch (uploadErr) {
            console.error("Error uploading image:", uploadErr);
          }
        }
      }

      const response = await queueImageGen(apiKey, {
        prompt: finalPrompt,
        model: selectedModel,
        references_urls: urlImages.length > 0 ? urlImages : undefined
      });

      if (response.success && response.task_id) {
        setLastRunHash(currentHash);
        startPolling(response.task_id, apiKey, currentHash);
      } else {
        setError(response.error || "Failed to queue generation.");
        setStatus("failed");
      }
    } catch (err) {
      setError("Network error.");
      setStatus("failed");
    }
  };

  const startPolling = async (taskId: string, apiKey: string, currentHash: string) => {
    setStatus("polling");

    const poll = async () => {
      try {
        const res = await getTaskStatus(apiKey, taskId);
        console.log("Polling status:", res);

        const isDone = res.status === 'succeeded' || (res.status as string) === 'completed' || (res.status as string) === 'success' || !!res.result_url;

        if (isDone && (res.result_url || (res as any).url || (res as any).image_url)) {
          const finalUrl = res.result_url || (res as any).url || (res as any).image_url;
          setResultUrl(finalUrl);
          setStatus("succeeded");
          // Save to node data
          setNodes(nds => nds.map(n => n.id === id ? { 
            ...n, 
            data: { ...n.data, resultUrl: finalUrl, lastRunHash: currentHash } 
          } : n));
          return true;
        } else if (res.status === 'failed' || (res.status as string) === 'error') {
          setError((res as any).error || (res as any).message || "Generation failed on server.");
          setStatus("failed");
          return true;
        }
        return false;
      } catch (e) {
        return false;
      }
    };

    // Poll every 3 seconds
    const interval = setInterval(async () => {
      const done = await poll();
      if (done) clearInterval(interval);
    }, 3000);
  };

  return (
    <div className={`w-80 bg-[#1a1525] rounded-lg shadow-2xl transition-all duration-200 relative ${
      selected 
        ? "border-2 border-[#fbbf24] shadow-[0_0_20px_rgba(251,191,36,0.3)]" 
        : "border-2 border-amber-500/30"
    }`}>
      <div className="bg-amber-900/20 px-4 py-3 flex items-center justify-between border-b border-amber-500/20 rounded-t-lg">
        <div className="flex items-center gap-2">
          <ImageDown className="w-5 h-5 text-amber-400" />
          <span className="font-bold text-xs text-amber-100 uppercase tracking-wider">PlenxAI Output</span>
        </div>
        {status !== 'idle' && (
          <div className="flex items-center gap-2">
            <span className="text-[10px] uppercase tracking-wider text-blue-400 font-bold animate-pulse">{status}</span>
          </div>
        )}
      </div>

      <div className="p-4 space-y-3">
        {/* Top/Middle: Handles List */}
        <div className="flex flex-col gap-1 pb-1">
          {(() => {
            const handlesToRender = [
              { id: 'text', color: '#3b82f6', isPlus: false }, // Blue for text
              ...imageInputs.map(id => ({ id, color: '#22c55e', isPlus: false })), // Green for images
            ];

            // Only show '+' if under 4 images
            if (imageInputs.length < 4) {
              handlesToRender.push({ id: 'image-plus', color: '#22c55e', isPlus: true });
            }

            return handlesToRender.map((h, i) => {
              if (h.isPlus) {
                return (
                  <div key={h.id} className="relative flex items-center h-6 mt-1">
                    <Handle
                      type="target"
                      position={Position.Left}
                      id={h.id}
                      className="!w-5 !h-5 !bg-[#22c55e] !border-none !flex !items-center !justify-center !min-w-0 !min-h-0 cursor-crosshair hover:scale-110 transition-transform shadow-md !left-[-24px]"
                      title="Drop wire here to add a new image input"
                    >
                      <span className="text-[#151b25] font-black text-lg leading-none mt-[-2px] ml-[1px]">+</span>
                    </Handle>
                    <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Add Image</span>
                  </div>
                );
              }

              return (
                <div key={h.id} className="relative flex items-center h-6">
                  <Handle
                    type="target"
                    id={h.id}
                    position={Position.Left}
                    style={{ backgroundColor: h.color }}
                    className={`!w-4 !h-4 !border-none !min-w-0 !min-h-0 !left-[-24px]`}
                  />
                  <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">
                    {h.id === 'text' ? 'Prompt Input' : `Reference Image`}
                  </span>
                </div>
              );
            });
          })()}
        </div>

        {/* Model Selection UI */}
        <div className="relative z-20">
          <label className="text-[10px] uppercase tracking-wider text-blue-400/60 font-bold mb-1 block">Generative Model</label>
          <button 
            onClick={() => setIsModelMenuOpen(!isModelMenuOpen)}
