import { useState, useEffect, useCallback } from "react";
import { Handle, Position, useReactFlow, useNodes, useEdges } from "reactflow";
import { Link2, MessageSquare, PlusCircle, ChevronDown, ChevronUp } from "lucide-react";

export default function PromptConnectorNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [collapsedStates, setCollapsedStates] = useState<Record<string, boolean>>({});
  const { setNodes, setEdges } = useReactFlow();
  const nodes = useNodes();
  const allEdges = useEdges();
  
  // Read state directly from React Flow node data (Master Blueprint)
  const handles: string[] = data.handles || ["text-h0", "text-h1"];
  const editableTexts: Record<string, string> = data.editableTexts || { "text-h0": "", "text-h1": "" };
  const everConnected: Record<string, boolean> = data.everConnected || {};

  // 1. Tracking "Ever Connected" status for handles
  useEffect(() => {
    const connectedHandleIds = allEdges
      .filter(e => e.target === id && e.targetHandle !== "text-plus")
      .map(e => e.targetHandle);
    
    let changed = false;
    const nextEver = { ...everConnected };
    connectedHandleIds.forEach(h => {
      if (h && !nextEver[h]) {
        nextEver[h] = true;
        changed = true;
      }
    });
    
    if (changed) {
      setNodes(nds => nds.map(n => n.id === id ? { 
        ...n, 
        data: { ...n.data, everConnected: nextEver } 
      } : n));
    }
  }, [allEdges, id, everConnected, setNodes]);

  // 2. Handle Auto-Deletion
  useEffect(() => {
    const edges = allEdges.filter(e => e.target === id);
    const connectedHandleIds = edges.map(e => e.targetHandle);

    // Handle removal of disconnected handles
    const nextHandles = handles.filter(h => {
      const isConnected = connectedHandleIds.includes(h);
      const isInitial = h === "text-h0" || h === "text-h1";
      const hasBeenUsed = everConnected[h];
      
      if (isConnected) return true;
      if (isInitial && !hasBeenUsed) return true;
      return false;
    });

    if (nextHandles.length !== handles.length) {
      const nextTexts = { ...editableTexts };
      handles.forEach(h => {
        if (!nextHandles.includes(h)) delete nextTexts[h];
      });

      setNodes(nds => nds.map(n => n.id === id ? { 
        ...n, 
        data: { ...n.data, handles: nextHandles, editableTexts: nextTexts } 
      } : n));
    }
  }, [allEdges, id, handles, everConnected, editableTexts, setNodes]);

  const updateEditable = (key: string, text: string) => {
    setNodes(nds => nds.map(n => n.id === id ? { 
      ...n, 
      data: { ...n.data, editableTexts: { ...(n.data.editableTexts || {}), [key]: text } } 
    } : n));
  };

  const getFragmentText = (handleId: string) => {
    const edge = allEdges.find(e => e.target === id && e.targetHandle === handleId);
    if (!edge) return null;
    const node = nodes.find(n => n.id === edge.source);
    return (node?.data as any)?.refinedText || (node?.data as any)?.text || (node?.data as any)?.bakedStyle || "";
  };

  // Compute final concatenated prompt
  useEffect(() => {
    const parts: string[] = [];
    
    handles.forEach(h => {
      if (editableTexts[h]) parts.push(editableTexts[h]);
      const fragText = getFragmentText(h);
      if (fragText !== null) parts.push(fragText);
    });
    
    const combinedText = parts.filter(t => t).join(" ");
    if (data.text !== combinedText) {
      setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, text: combinedText } } : n));
    }
  }, [handles, editableTexts, nodes, allEdges, id, setNodes, data.text]);

  const COLORS = [
    'bg-blue-500/20 border-blue-500/50 text-blue-200',
    'bg-emerald-500/20 border-emerald-500/50 text-emerald-200',
    'bg-emerald-500/20 border-emerald-500/50 text-emerald-200',
    'bg-amber-500/20 border-amber-500/50 text-amber-200',
    'bg-rose-500/20 border-rose-500/50 text-rose-200',
  ];

  return (
    <div className={`w-80 bg-[#1a1525] rounded-lg shadow-2xl border-2 transition-all duration-200 relative ${
      selected ? "border-[#fbbf24] shadow-[0_0_20px_rgba(251,191,36,0.3)]" : "border-blue-500/30"
    }`}>
      <div className="bg-blue-900/20 px-3 py-2 flex items-center justify-between border-b border-blue-500/20 rounded-t-lg">
        <div className="flex items-center gap-2">
          <Link2 className="w-4 h-4 text-blue-400" />
          <span className="font-bold text-xs text-blue-100 uppercase tracking-wider">Prompt Connector</span>
        </div>
      </div>

      <div className="p-3 space-y-4 overflow-visible">
        {/* Dynamic Handle Slots */}
        {handles.map((hId, idx) => {
          const fragText = getFragmentText(hId);
          const isConnected = fragText !== null;
          
          return (
            <div key={hId} className="space-y-2 group/slot">
              {/* Per-handle Context Textbox */}
              <textarea
                className="nodrag w-full min-h-[30px] bg-transparent text-gray-400 text-sm p-1 focus:outline-none focus:ring-1 focus:ring-blue-500/30 rounded resize-none placeholder:text-gray-600 overflow-hidden"
                placeholder="Type additional context..."
                value={editableTexts[hId] || ""}
                onInput={(e: any) => {
                  e.target.style.height = 'auto';
                  e.target.style.height = e.target.scrollHeight + 'px';
                }}
                onChange={(e) => updateEditable(hId, e.target.value)}
                ref={(el) => {
                  if (el) {
                    el.style.height = 'auto';
                    el.style.height = el.scrollHeight + 'px';
                  }
                }}
              />

              {/* Receiver Box */}
              <div className="relative">
                {/* Receiver Handle */}
                <Handle
                  type="target"
                  position={Position.Left}
                  id={hId}
                  className={`!w-4 !h-4 !bg-blue-500 !border-none !min-w-0 !min-h-0 !left-[-22px] transition-all duration-200 ${
                    isConnected ? "!scale-110" : ""
                  }`}
                  style={{ top: "50%", transform: "translateY(-50%)" }}
                  title={`Input ${hId}`}
                />

                {isConnected ? (
                  <div className={`relative px-3 py-2.5 rounded-lg border text-xs font-medium leading-relaxed shadow-sm transition-all ${COLORS[idx % COLORS.length]}`}>
                    <div className="flex items-center justify-between mb-1 opacity-60">
                      <div className="flex items-center gap-1">
                        <MessageSquare className="w-3 h-3" />
                        <span>Linked Fragment</span>
                      </div>
                      {fragText && fragText.length > 100 && (
                        <button 
                          onClick={() => setCollapsedStates(prev => ({ ...prev, [hId]: !prev[hId] }))}
                          className="absolute top-1 right-1 hover:text-white transition-colors bg-[#1a1525]/80 p-0.5 rounded shadow-sm"
                        >
                          {collapsedStates[hId] === false ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
                        </button>
                      )}
                    </div>
                    <div className={`leading-snug ${collapsedStates[hId] !== false ? "max-h-12 overflow-hidden" : ""}`}>
                      {fragText || <span className="italic opacity-40 text-[10px]">No text content...</span>}
                    </div>
                  </div>
                ) : (
                  <div className="h-16 w-full bg-[#1b253b] rounded-xl border border-blue-500/10 shadow-inner"></div>
                )}
              </div>
            </div>
          );
        })}

        {/* The "+" Spawner Handle */}
        <div className="relative h-6 mt-2">
          <Handle
            type="target"
            position={Position.Left}
            id="text-plus"
            className="!w-5 !h-5 !bg-blue-500 !border-none !flex !items-center !justify-center !min-w-0 !min-h-0 !left-[-24px] cursor-crosshair hover:scale-110 transition-transform shadow-md"
            style={{ top: '50%', transform: 'translateY(-50%)' }}
            title="Drop wire here to add a new input"
          >
            <span className="text-[#121826] font-black text-lg leading-none mt-[-2px] ml-[1px]">+</span>
          </Handle>
        </div>
      </div>

      {/* Main Output Handle */}
      <Handle
        type="source"
        position={Position.Right}
        id="text"
        className="!w-4 !h-4 !bg-[#3b82f6] !border-none !min-w-0 !min-h-0"
      />
    </div>
  );
}

import { useState, useCallback } from "react";
import { Handle, Position, useReactFlow } from "reactflow";
import { Image as ImageIcon, UploadCloud, X } from "lucide-react";

export default function ReferenceImageNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [imagePreview, setImagePreview] = useState<string | null>(data.imageUrl || null);
  const { setNodes } = useReactFlow();

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const url = event.target?.result as string;
        setImagePreview(url);
        setNodes((nds) =>
          nds.map((node) =>
            node.id === id ? { ...node, data: { ...node.data, imageUrl: url } } : node
          )
        );
      };
      reader.readAsDataURL(file);
    }
  };

  const removeImage = () => {
    setImagePreview(null);
    setNodes((nds) =>
      nds.map((node) =>
        node.id === id ? { ...node, data: { ...node.data, imageUrl: null } } : node
      )
    );
  };

  return (
    <div className={`w-64 bg-[#1a1525] rounded-lg shadow-2xl transition-all duration-200 relative ${
      selected 
        ? "border-2 border-[#fbbf24] shadow-[0_0_20px_rgba(251,191,36,0.3)]" 
        : "border-2 border-emerald-500/30"
    }`}>
      <div className="bg-emerald-900/20 px-3 py-2 flex items-center gap-2 border-b border-emerald-500/20 rounded-t-lg">
        <ImageIcon className="w-4 h-4 text-emerald-400" />
        <span className="font-bold text-xs text-emerald-100 uppercase tracking-wider">Image Input</span>
      </div>
      <div className="p-3">
        {imagePreview ? (
          <div className="relative w-full rounded overflow-hidden border border-emerald-500/20 bg-black/50">
            <img src={imagePreview} className="w-full h-auto block" alt="reference" />
            <button 
              onClick={removeImage}
              className="nodrag absolute top-1 right-1 p-1 bg-black/60 rounded-full hover:bg-black/80 transition-colors"
            >
              <X className="w-3 h-3 text-white" />
            </button>
          </div>
        ) : (
          <label className="w-full aspect-video rounded border-2 border-dashed border-emerald-500/20 flex flex-col items-center justify-center hover:border-emerald-500/50 cursor-pointer transition-colors bg-black/20 text-emerald-400/40">
            <UploadCloud className="w-8 h-8 mb-1" />
            <span className="text-xs">Upload Image</span>
            <input type="file" className="hidden nodrag" onChange={handleUpload} accept="image/*" />
          </label>
        )}
      </div>
      <Handle
        type="source"
        position={Position.Right}
        id="image"
        className="!w-4 !h-4 !bg-[#22c55e] !border-none !min-w-0 !min-h-0"
      />
    </div>
  );
}

import { useState, useCallback, useEffect } from "react";
import { Handle, Position, useReactFlow } from "reactflow";
import { Palette, UploadCloud, RefreshCw, Sparkles, X, ChevronDown, ChevronUp } from "lucide-react";
import { fetchNodePrompt, TEXT_MODELS } from "@/lib/plenxai";
import { GOOGLE_MODELS } from "@/lib/gemini";
import { generateTextUniversal } from "@/lib/llm-router";

export default function StyleInsertNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [images, setImages] = useState<string[]>(data.images || []);
  const [isBaking, setIsBaking] = useState(false);
  const [bakedStyle, setBakedStyle] = useState<string>(data.bakedStyle || "");
  const [generatedPrompt, setGeneratedPrompt] = useState<string>(data.generatedPrompt || "");
  const [isCollapsed, setIsCollapsed] = useState(true);
  const [isPromptCollapsed, setIsPromptCollapsed] = useState(true);
  const [selectedModel, setSelectedModel] = useState<string>(data.model || "gemini-2.5-flash");
  const [isModelMenuOpen, setIsModelMenuOpen] = useState(false);
  const [textProvider, setTextProvider] = useState<"plenxai" | "google">("plenxai");
  const { setNodes } = useReactFlow();

  useEffect(() => {
    setTextProvider((localStorage.getItem("artist-assistant-text-provider") as any) || "plenxai");
    const handleProviderChange = (e: any) => setTextProvider(e.detail);
    window.addEventListener("text-provider-changed", handleProviderChange);
    return () => window.removeEventListener("text-provider-changed", handleProviderChange);
  }, []);

  const activeModels = textProvider === "google" ? GOOGLE_MODELS : TEXT_MODELS;

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && images.length < 4) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const newImages = [...images, event.target?.result as string];
        setImages(newImages);
        setNodes((nds) =>
          nds.map((node) =>
            node.id === id ? { ...node, data: { ...node.data, images: newImages } } : node
          )
        );
      };
      reader.readAsDataURL(file);
    }
  };

  const removeImage = (index: number) => {
    const newImages = images.filter((_, i) => i !== index);
    setImages(newImages);
    setNodes((nds) =>
      nds.map((node) =>
        node.id === id ? { ...node, data: { ...node.data, images: newImages } } : node
      )
    );
  };

  const bakeStyle = async () => {
    if (images.length === 0) return;

    setIsBaking(true);
    try {
      let prompt = await fetchNodePrompt('StyleInsertNode');
      if (!prompt) prompt = "Analyze the artistic style, color palette, lighting, and mood of these images. Create a concise 'Style Signature' (1-2 sentences) that can be used to replicate this style in other prompts.";
      
      setGeneratedPrompt(prompt);
      setNodes((nds) => nds.map((node) => node.id === id ? { ...node, data: { ...node.data, generatedPrompt: prompt } } : node));

      const response = await generateTextUniversal(prompt, images, selectedModel);
      if (response.success && response.text) {
        setBakedStyle(response.text);
        setNodes((nds) =>
          nds.map((node) =>
            node.id === id ? { ...node, data: { ...node.data, bakedStyle: response.text } } : node
          )
        );
      } else {
        alert("Baking failed: " + (response.error || (response as any).message || JSON.stringify(response)));
      }
    } catch (error) {
      console.error(error);
      alert("Error baking style.");
    } finally {
      setIsBaking(false);
    }
  };

  return (
    <div className={`w-72 bg-[#1a1525] rounded-lg shadow-2xl transition-all duration-200 relative ${
      selected 
        ? "border-2 border-[#fbbf24] shadow-[0_0_20px_rgba(251,191,36,0.3)]" 
        : "border-2 border-emerald-500/30"
    }`}>
      <div className="bg-emerald-900/20 px-3 py-2 flex items-center justify-between border-b border-emerald-500/20 rounded-t-lg">
        <div className="flex items-center gap-2">
          <Palette className="w-4 h-4 text-emerald-400" />
          <span className="font-bold text-xs text-emerald-100 uppercase tracking-wider">Style Insert</span>
        </div>
        {bakedStyle && <Sparkles className="w-3 h-3 text-yellow-400 animate-pulse" />}
      </div>

      <div className="p-3 space-y-3">
        <div className="grid grid-cols-2 gap-2">
          {images.map((img, i) => (
            <div key={i} className="relative aspect-square rounded bg-black/40 overflow-hidden border border-emerald-500/20 group/img flex items-center justify-center">
              <img src={img} className="max-w-full max-h-full object-contain" alt="style" />
              <button 
                onClick={() => removeImage(i)}
                className="nodrag absolute top-1 right-1 p-1 bg-black/60 rounded-full opacity-0 group-hover/img:opacity-100 transition-opacity"
              >
                <X className="w-3 h-3 text-white" />
              </button>
            </div>
          ))}
          {images.length < 4 && (
            <label className="aspect-square rounded border-2 border-dashed border-emerald-500/20 flex flex-col items-center justify-center hover:border-emerald-500/50 cursor-pointer transition-colors bg-black/20 text-emerald-400/40">
              <UploadCloud className="w-6 h-6" />
              <input type="file" className="hidden nodrag" onChange={handleUpload} accept="image/*" />
            </label>
          )}
        </div>

        <div className="relative z-20">
          <label className="text-[10px] uppercase tracking-wider text-emerald-400/60 font-bold mb-1 block">Generative Model</label>
          <button 
            onClick={() => setIsModelMenuOpen(!isModelMenuOpen)}
            className="nodrag w-full bg-black/40 border border-emerald-500/20 rounded px-3 py-2 flex items-center justify-between hover:border-emerald-500/40 transition-colors"
          >
            <span className="text-xs text-emerald-100 font-medium">
              {activeModels.find(m => m.id === selectedModel)?.name || "Select Model"}
            </span>
            <ChevronDown className={`w-4 h-4 text-emerald-400 transition-transform ${isModelMenuOpen ? 'rotate-180' : ''}`} />
          </button>
          
          {isModelMenuOpen && (
            <div className="absolute top-full left-0 right-0 mt-1 bg-[#1a2230] border border-emerald-500/30 rounded shadow-2xl overflow-hidden animate-in fade-in z-30">
              {activeModels.map((m) => (
                <button
                  key={m.id}
                  onClick={() => {
                    setSelectedModel(m.id);
                    setIsModelMenuOpen(false);
                    setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, model: m.id } } : n));
                  }}
                  className={`w-full px-3 py-2 text-left text-xs transition-colors hover:bg-emerald-600/20 ${
                    selectedModel === m.id ? 'text-emerald-400 font-bold bg-emerald-600/10' : 'text-emerald-100/70'
                  }`}
                >
                  {m.name}
                </button>
              ))}
            </div>
          )}
        </div>



        {bakedStyle ? (
          <div className="relative group">
            <div className={`bg-black/40 border border-emerald-500/20 p-2 rounded text-[10px] text-emerald-100/70 italic whitespace-pre-wrap ${isCollapsed ? "max-h-24 overflow-hidden" : ""}`}>
              <div className="text-emerald-400 font-bold mb-1">Style Signature:</div>
              {bakedStyle}
            </div>
            {bakedStyle.length > 80 && (
              <button 
                onClick={() => setIsCollapsed(!isCollapsed)}
                className="absolute top-1 right-1 text-emerald-400 hover:text-emerald-300 transition-colors bg-[#1a1525]/80 p-0.5 rounded shadow-sm"
              >
                {isCollapsed ? <ChevronDown className="w-3.5 h-3.5" /> : <ChevronUp className="w-3.5 h-3.5" />}
              </button>
            )}
          </div>
        ) : (
          <p className="text-[10px] text-emerald-400/40 text-center">Upload up to 4 images to bake a style signature.</p>
        )}

        <button 
          onClick={bakeStyle}
          disabled={isBaking || images.length === 0}
          className={`nodrag w-full py-2 rounded text-xs font-medium flex items-center justify-center gap-2 transition-all ${
            isBaking 
              ? "bg-emerald-600/50 cursor-not-allowed" 
              : "bg-emerald-600 hover:bg-emerald-500 text-white"
          }`}
        >
          {isBaking ? <RefreshCw className="w-3 h-3 animate-spin" /> : <Sparkles className="w-3 h-3" />}
          {isBaking ? "Baking Style..." : "Bake Style"}
        </button>
      </div>

      <Handle
        type="source"
        position={Position.Right}
        id="text"
        className="!w-4 !h-4 !bg-[#3b82f6] !border-none !min-w-0 !min-h-0"
      />
    </div>
  );
}

import { useState, useCallback, useEffect } from "react";
import { Handle, Position, useReactFlow, useUpdateNodeInternals, useEdges } from "reactflow";
import { ImageIcon, RefreshCw, Play, AlertCircle, Download, ChevronDown, Eye } from "lucide-react";
import { queueImageGen, getTaskStatus, uploadMediaDirect, fetchNodePrompt } from "@/lib/plenxai";

const MODELS = [
  { id: "nano-banana-pro", name: "Nano Banana PRO" },
  { id: "nano-banana-full", name: "Nano Banana Full" },
  { id: "nano-banana-2", name: "Nano Banana 2" },
  { id: "kling-o1-image", name: "Kling O1 Image" },
  { id: "flux-2-pro", name: "Flux 2 Pro" },
  { id: "seedream-5-lite", name: "Seedream 5 Lite" },
  { id: "seedream-4-5", name: "Seedream 4.5" },
  { id: "grok-image", name: "Grok Image" },
  { id: "gpt-image-2", name: "GPT Image 2" }
];

export default function TilesetGeneratorNode({ id, data, selected }: { id: string; data: any; selected?: boolean }) {
  const [status, setStatus] = useState<"idle" | "queueing" | "polling" | "succeeded" | "failed">("idle");
  const [resultUrl, setResultUrl] = useState<string | null>(data.resultUrl || null);
  const [error, setError] = useState<string | null>(null);
  const [lastRunHash, setLastRunHash] = useState<string>(data.lastRunHash || "");
  const [selectedModel, setSelectedModel] = useState<string>(data.model || MODELS[0].id);
  const [isModelMenuOpen, setIsModelMenuOpen] = useState(false);
  const [localPrompt, setLocalPrompt] = useState<string>(data.localPrompt || "");
  const [showApiPrompt, setShowApiPrompt] = useState(false);
  const [apiPromptPreview, setApiPromptPreview] = useState<string>(data.apiPromptPreview || "");
  
  const { getNodes, getEdges, setNodes } = useReactFlow();
  const updateNodeInternals = useUpdateNodeInternals();

  const generateImage = async () => {
    // Gather Inputs
    const nodes = getNodes();
    const edges = getEdges();
    const incomingEdges = edges.filter(e => e.target === id);
    
    const promptParts: string[] = [];
    if (localPrompt) promptParts.push(localPrompt);

    let styleInput = "";
    let inputImageUrl = "";

    incomingEdges.forEach(edge => {
      const sourceNode = nodes.find(n => n.id === edge.source);
      if (!sourceNode) return;
      if (edge.targetHandle === 'text') {
        const text = sourceNode.data.refinedText || sourceNode.data.text || sourceNode.data.bakedStyle || "";
        if (text) promptParts.push(text);
      }
      if (edge.targetHandle === 'style') {
        styleInput = sourceNode.data.refinedText || sourceNode.data.text || sourceNode.data.bakedStyle || "";
      }
      if (edge.targetHandle === 'image') {
        inputImageUrl = sourceNode.data.imageUrl || sourceNode.data.resultUrl || sourceNode.data.image || "";
      }
    });

    const themePrompt = promptParts.join(", ") || "Fantasy terrain";
    const styleString = styleInput || "Game art, isometric";

    let baseApiPrompt = await fetchNodePrompt('TilesetGeneratorNode');
    if (!baseApiPrompt) {
      baseApiPrompt = `You are a technical game artist. Your task is to re-skin the provided reference image, {1x1_Island_Default.jpg}, into a new game-ready island base while maintaining a 1:1 pixel-perfect silhouette match.

1. Structural Integrity:
The X-Island: Generate the upper X-shaped structure as a cohesive island base. This structure must perfectly align with the 13-component tile layout seen in {1x1_Island_Default.jpg}. The top surface and the vertical rocky side-walls must stay within the exact geometric boundaries of the reference.
The Component Block: Generate the single isolated island cell directly below the main island. This block must match the material of the main island and sit in the identical pixel coordinates as the reference block in {1x1_Island_Default.jpg}.

2. Dynamic Theme & Style:
THEME: {theme}
ARTSTYLE: {style}
Visual DNA: Apply the specified {theme} to all surfaces. Use the {style} to dictate the shape language (e.g., chunky/puffy edges, soft gradients, or specific texture detailing). Match the lighting logic—including highlight and shadow directions—to ensure the 13 components can be tiled seamlessly.

3. Masking & Extraction Constraints:
Background: Fill all non-object space with a flat, solid black (000000).
No Artifacts: DO NOT include any ground shadows, floor planes, horizon lines, or atmospheric effects.
No Spill: Ensure there is no neon green light reflected onto the island rocks or surfaces. Edges must be sharp and aliased to the object boundary.

4. Final Specs:
Reference: {1x1_Island_Default.jpg}
Resolution: {resolution} (1:1 Ratio)
View: Strict 30-degree isometric.`;
    }

    const apiPrompt = baseApiPrompt
      .replace(/{theme}/g, themePrompt)
      .replace(/{style}/g, styleString)
      .replace(/{resolution}/gi, "2k")
      .replace(/{1x1_Island_Default\.jpg}/gi, "the reference image");
    
    setApiPromptPreview(apiPrompt);
    setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, apiPromptPreview: apiPrompt } } : n));

    const currentHash = JSON.stringify({ prompt: apiPrompt, model: selectedModel });

    if (status === 'succeeded' && currentHash === lastRunHash && resultUrl) {
      console.log("No changes detected, skipping API call.");
      return;
    }

    const apiKey = localStorage.getItem("artist-assistant-image-api");
    if (!apiKey) {
      setError("Please enter PlenxAI API Key in Settings.");
      setStatus("failed");
      return;
    }

    if (!themePrompt) {
      setError("No prompt detected.");
      setStatus("failed");
      return;
    }

    setStatus("queueing");
    setError(null);

    try {
      // Fetch the local default island and upload it to get a CDN URL for the API
      const imgRes = await fetch('/assets/hex-tool/1x1_Island_Default.png');
      const blob = await imgRes.blob();
      const reader = new FileReader();
      const base64Data: string = await new Promise((resolve) => {
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(blob);
      });

      const uploadRes = await uploadMediaDirect(apiKey, base64Data);
      const referenceUrl = uploadRes.url || uploadRes.cdn_url;
      
      if (!referenceUrl) {
        throw new Error("Failed to upload reference template to AI server.");
      }

      let additionalReferenceUrl = "";
      if (inputImageUrl) {
        if (inputImageUrl.startsWith('data:image/')) {
          const uploadRes = await uploadMediaDirect(apiKey, inputImageUrl);
          additionalReferenceUrl = uploadRes.url || uploadRes.cdn_url;
        } else if (inputImageUrl.startsWith('blob:')) {
          const imgRes = await fetch(inputImageUrl);
          const blob = await imgRes.blob();
          const reader = new FileReader();
          const base64Data: string = await new Promise((resolve) => {
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(blob);
          });
          const uploadRes = await uploadMediaDirect(apiKey, base64Data);
          additionalReferenceUrl = uploadRes.url || uploadRes.cdn_url;
        } else if (inputImageUrl.startsWith('http')) {
          additionalReferenceUrl = inputImageUrl;
        }
      }

      const referencesUrls = [referenceUrl];
      if (additionalReferenceUrl) {
        referencesUrls.push(additionalReferenceUrl);
      }

      const response = await queueImageGen(apiKey, {
        prompt: apiPrompt,
        model: selectedModel,
        resolution: "2k",
        aspect_ratio: "1:1",
        references_urls: referencesUrls
      });

      if (response.success && response.task_id) {
        setLastRunHash(currentHash);
        startPolling(response.task_id, apiKey, currentHash);
      } else {
        setError(response.error || "Failed to queue generation.");
        setStatus("failed");
      }
    } catch (err) {
      setError("Network error.");
      setStatus("failed");
    }
  };

  const startPolling = async (taskId: string, apiKey: string, currentHash: string) => {
    setStatus("polling");
    
    const poll = async () => {
      try {
        const res = await getTaskStatus(apiKey, taskId);
        
        const isDone = res.status === 'succeeded' || (res.status as string) === 'completed' || (res.status as string) === 'success' || !!res.result_url;
        
        if (isDone && (res.result_url || (res as any).url || (res as any).image_url)) {
          const finalUrl = res.result_url || (res as any).url || (res as any).image_url;
          setResultUrl(finalUrl);
          setStatus("succeeded");
          setNodes(nds => nds.map(n => n.id === id ? { 
            ...n, 
            data: { ...n.data, resultUrl: finalUrl, lastRunHash: currentHash, localPrompt } 
          } : n));
          return true;
        } else if (res.status === 'failed' || (res.status as string) === 'error') {
          setError((res as any).error || (res as any).message || "Generation failed.");
          setStatus("failed");
          return true;
        }
        return false;
      } catch (e) {
        return false;
      }
    };

    const interval = setInterval(async () => {
      const done = await poll();
      if (done) clearInterval(interval);
    }, 3000);
  };

  return (
    <div className={`w-80 bg-[#1a1525] rounded-lg shadow-2xl transition-all duration-200 relative ${
      selected ? "border-2 border-[#fbbf24]" : "border-2 border-indigo-500/30"
    }`}>
      <div className="bg-indigo-900/20 px-4 py-3 flex items-center justify-between border-b border-indigo-500/20 rounded-t-lg">
        <div className="flex items-center gap-2">
          <ImageIcon className="w-5 h-5 text-indigo-400" />
          <span className="font-bold text-xs text-indigo-100 uppercase tracking-wider">Tileset Generator</span>
        </div>
        {status !== 'idle' && (
          <div className="flex items-center gap-2">
            <span className="text-[10px] uppercase tracking-wider text-blue-400 font-bold animate-pulse">{status}</span>
          </div>
        )}
      </div>
      
      <div className="p-4 space-y-3">
        <div className="relative">
          <Handle type="target" position={Position.Left} id="text" className="!w-4 !h-4 !bg-[#3b82f6] !border-none !left-[-24px] top-1/2" />
          <textarea
            className="nodrag text-xs w-full bg-black/40 text-gray-200 p-2 rounded border border-indigo-500/20 focus:border-indigo-500/60 focus:outline-none resize-none"
            placeholder="Enter theme (e.g., Lava rocks, glowing magma...)"
            rows={3}
            value={localPrompt}
            onChange={(e) => setLocalPrompt(e.target.value)}
          />
        </div>

        <div className="flex flex-col gap-1">
          <div className="relative flex items-center h-6">
            <Handle type="target" position={Position.Left} id="style" className="!w-4 !h-4 !bg-[#3b82f6] !border-none !left-[-24px]" />
            <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Style Input</span>
          </div>
          <div className="relative flex items-center h-6">
            <Handle type="target" position={Position.Left} id="image" className="!w-4 !h-4 !bg-[#22c55e] !border-none !left-[-24px]" />
            <span className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">Blueprint Image</span>
          </div>
        </div>

        {/* Model Selection UI */}
        <div className="relative z-20">
          <label className="text-[10px] uppercase tracking-wider text-indigo-400/60 font-bold mb-1 block">Generative Model</label>
          <button 
            onClick={() => setIsModelMenuOpen(!isModelMenuOpen)}
            className="nodrag w-full bg-black/40 border border-indigo-500/20 rounded px-3 py-2 flex items-center justify-between hover:border-indigo-500/40 transition-colors"
          >
            <span className="text-xs text-indigo-100 font-medium">
              {MODELS.find(m => m.id === selectedModel)?.name || "Select Model"}
            </span>
            <ChevronDown className={`w-4 h-4 text-indigo-400 transition-transform ${isModelMenuOpen ? 'rotate-180' : ''}`} />
          </button>
          
          {isModelMenuOpen && (
            <div className="absolute top-full left-0 right-0 mt-1 bg-[#1a2230] border border-indigo-500/30 rounded shadow-2xl overflow-hidden animate-in fade-in">
              {MODELS.map((m) => (
                <button
                  key={m.id}
                  onClick={() => {
                    setSelectedModel(m.id);
                    setIsModelMenuOpen(false);
                    setNodes(nds => nds.map(n => n.id === id ? { ...n, data: { ...n.data, model: m.id } } : n));
                  }}
                  className={`w-full px-3 py-2 text-left text-xs transition-colors hover:bg-indigo-600/20 ${
                    selectedModel === m.id ? 'text-indigo-400 font-bold bg-indigo-600/10' : 'text-indigo-100/70'
                  }`}
                >
                  {m.name}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Image Preview */}
        <div className="w-full aspect-square bg-black/50 border border-indigo-500/20 rounded overflow-hidden flex flex-col items-center justify-center relative">
          {resultUrl ? (
            <img src={resultUrl} className="w-full h-full object-contain" alt="generated tileset" />
          ) : (
            <>
              {(status === 'queueing' || status === 'polling') ? (
                <RefreshCw className="w-8 h-8 text-indigo-500 animate-spin" />
              ) : (
                <ImageIcon className="w-8 h-8 mb-2 opacity-20 text-indigo-500" />
              )}
            </>
          )}
          
          {error && (
            <div className="absolute inset-x-0 bottom-0 bg-red-900/80 p-2 flex items-start gap-2 border-t border-red-500/50">
              <AlertCircle className="w-4 h-4 text-red-200 shrink-0 mt-0.5" />
              <span className="text-[10px] text-red-100">{error}</span>
            </div>
          )}
        </div>

        {/* API Prompt Toggle */}
        <div className="pt-1">
          <button 
            onClick={() => setShowApiPrompt(!showApiPrompt)}
            className="nodrag flex items-center gap-1 text-[10px] text-indigo-400 hover:text-indigo-300 font-bold uppercase tracking-wider"
          >
            <Eye className="w-3 h-3" />
            {showApiPrompt ? "Hide API Prompt" : "View API Prompt"}
          </button>
          {showApiPrompt && (
            <div className="mt-2 p-2 bg-black/60 border border-indigo-500/30 rounded text-[10px] text-indigo-200/80 break-words leading-relaxed max-h-24 overflow-y-auto">
              {apiPromptPreview || "Generate first to see the full API prompt..."}
            </div>
          )}
        </div>
        
        <div className="flex gap-2">
          <button 
            onClick={generateImage}
            disabled={status === 'queueing' || status === 'polling'}
            className="nodrag flex-[2] py-2 bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-bold rounded shadow-lg flex items-center justify-center gap-2 disabled:opacity-50 transition-all"
          >
            <Play className="w-4 h-4 fill-current" />
            GENERATE
          </button>
        </div>
      </div>

      <Handle type="source" position={Position.Right} id="image" className="!w-4 !h-4 !bg-[#22c55e] !border-none !right-[-8px]" />
    </div>
  );
}

import { generateText as plenxaiGenerateText, explainImage as plenxaiExplainImage, fetchNodePrompt } from "./plenxai";
import { generateGeminiText } from "./gemini";

export interface LLMRouterResponse {
  success: boolean;
  text?: string;
  error?: string;
}

/**
 * Universal wrapper to route text generation to either PlenxAI or directly to Google Gemini
 */
export async function generateTextUniversal(prompt: string, images?: string[], model: string = "gemini-2.5-flash"): Promise<LLMRouterResponse> {
  const provider = localStorage.getItem("artist-assistant-text-provider") || "plenxai";

  if (provider === "google") {
    const key = localStorage.getItem("artist-assistant-google-api");
    if (!key) return { success: false, error: "Missing Google API Key! Please enter it in the Settings menu." };

    let geminiModel = "gemini-2.5-flash";

    if (model.includes("pro") || model.includes("gpt") || model.includes("claude")) {
      geminiModel = "gemini-2.5-pro";
    } else if (model.includes("flash")) {
      geminiModel = "gemini-2.5-flash";
    }

    const response = await generateGeminiText(key, prompt, images, geminiModel);
    return response;
  } else {
    const key = localStorage.getItem("artist-assistant-image-api");
    if (!key) return { success: false, error: "Missing PlenxAI API Key! Please enter it in the Settings menu." };

    const response = await plenxaiGenerateText(key, prompt, images, model);
    return response;
  }
}

/**
 * Universal wrapper for Image Explained node
 */
export async function explainImageUniversal(images: string[], customPrompt?: string, model: string = "gemini-2.5-flash"): Promise<LLMRouterResponse> {
  let prompt = customPrompt;
  if (!prompt) {
    prompt = await fetchNodePrompt('ImageExplainedNode');
  }

  return generateTextUniversal(prompt, images, model);
}

export interface PlacedObject {
  url: string;
  id: string;
  instanceId: string;
  cellX: number;
  cellY: number;
  layer?: number;
  lx: number;
  ly: number;
  baseTiles?: {lx: number, ly: number}[];
}

export interface MapGridCell {
  x: number;
  y: number;
  layer?: number;
  isLand: boolean;
  isTopFace?: boolean;
  tileId?: string;
  objects: PlacedObject[];
  distance?: number;
  rawDistance?: number;
}

class SeededRandom {
  private seed: number;
  constructor(seed: number) {
    this.seed = seed;
  }
  next() {
    this.seed = (this.seed * 9301 + 49297) % 233280;
    return this.seed / 233280;
  }
}

export class TerrainGenerator {
  static generate(canvasWidth: number, canvasHeight: number, islandWidth: number, islandHeight: number, seed: number, noiseScale: number, objectAssets: any[] = [], groundOverrides: Record<string, number> = {}, levels: number[] = [1]): Record<number, MapGridCell[][]> {
    const cw = Number(canvasWidth);
    const ch = Number(canvasHeight);
    const iw = Number(islandWidth);
    const ih = Number(islandHeight);
    const rng = new SeededRandom(seed);
    const results: Record<number, MapGridCell[][]> = {};
    
    const startX = Math.floor((cw - iw) / 2);
    const startY = Math.floor((ch - ih) / 2);

    for (const level of levels) {
      // Create empty canvas grid
      const grid: boolean[][] = [];
      for (let y = 0; y < ch; y++) {
        grid[y] = new Array(cw).fill(false);
      }

      if (level === 1) {
        // Generate island within iw x ih
        const islandGrid: boolean[][] = [];
        for (let y = 0; y < ih; y++) {
          const row: boolean[] = [];
          for (let x = 0; x < iw; x++) {
            const cx = iw / 2;
            const cy = ih / 2;
            const dx = (x - cx) / cx;
            const dy = (y - cy) / cy;
            const dist = Math.sqrt(dx*dx + dy*dy);
            
            let landProb = 1.0 - (dist * 1.5);
            landProb += (rng.next() - 0.5) * noiseScale * 2;
            row.push(landProb > 0.3);
          }
          islandGrid.push(row);
        }

        // Cellular Automata on islandGrid
        for (let i = 0; i < 3; i++) {
          const newGrid = islandGrid.map(row => [...row]);
          for (let y = 0; y < ih; y++) {
            for (let x = 0; x < iw; x++) {
              let neighbors = 0;
              for (let dy = -1; dy <= 1; dy++) {
                for (let dx = -1; dx <= 1; dx++) {
                  if (dx === 0 && dy === 0) continue;
                  const nx = x + dx;
                  const ny = y + dy;
                  if (nx >= 0 && nx < iw && ny >= 0 && ny < ih) {
                    if (islandGrid[ny][nx]) neighbors++;
                  }
                }
              }
              if (islandGrid[y][x]) {
                newGrid[y][x] = neighbors >= 3;
              } else {
                newGrid[y][x] = neighbors >= 5;
              }
            }
          }
          for (let y = 0; y < ih; y++) {
            for (let x = 0; x < iw; x++) {
              islandGrid[y][x] = newGrid[y][x];
            }
          }
        }

        // Copy islandGrid into main grid at startX, startY
        for (let y = 0; y < ih; y++) {
          for (let x = 0; x < iw; x++) {
             if (startY + y >= 0 && startY + y < ch && startX + x >= 0 && startX + x < cw) {
                grid[startY + y][startX + x] = islandGrid[y][x];
             }
          }
        }
      }

      // Apply overrides
      for (let y = 0; y < ch; y++) {
        for (let x = 0; x < cw; x++) {
           const overrideKey = `${level},${x},${y}`;
           if (groundOverrides.hasOwnProperty(overrideKey)) {
             grid[y][x] = groundOverrides[overrideKey] === 1;
           }
        }
      }

      // Enforce constraints on the full grid
      let changed = true;
      let passes = 0;
      while (changed && passes < 10) {
        changed = false;
        passes++;

        // Keep only largest connected component (only on level 1 procedural generation if no overrides... wait, constraints should apply regardless, but maybe we shouldn't wipe disconnected islands if they are manual edits? Let's skip largest component if manual overrides exist. For now, keep it simple: keep largest connected component over the entire canvas)
        const visited: boolean[][] = Array(ch).fill(false).map(() => Array(cw).fill(false));
        let largestComponent: {x:number, y:number}[] = [];
        
        for (let y = 0; y < ch; y++) {
          for (let x = 0; x < cw; x++) {
            if (grid[y][x] && !visited[y][x]) {
              const comp: {x:number, y:number}[] = [];
              const queue = [{x, y}];
              visited[y][x] = true;
              
              while(queue.length > 0) {
                const curr = queue.shift()!;
                comp.push(curr);
                
                const neighbors = [
                  {x: curr.x, y: curr.y-1}, {x: curr.x, y: curr.y+1},
                  {x: curr.x-1, y: curr.y}, {x: curr.x+1, y: curr.y}
                ];
                
                for (const n of neighbors) {
                  if (n.x >= 0 && n.x < cw && n.y >= 0 && n.y < ch && grid[n.y][n.x] && !visited[n.y][n.x]) {
                    visited[n.y][n.x] = true;
                    queue.push(n);
                  }
                }
              }
              if (comp.length > largestComponent.length) {
                largestComponent = comp;
              }
            }
          }
        }
        
        // Clear everything not in largest component
        // Note: manual overrides might be disconnected, but for procedural coherence we enforce it.
        for (let y = 0; y < ch; y++) {
          for (let x = 0; x < cw; x++) {
            grid[y][x] = false;
          }
        }
        for (const cell of largestComponent) {
          grid[cell.y][cell.x] = true;
        }

        for (let y = 0; y < ch; y++) {
          for (let x = 0; x < cw; x++) {
            if (!grid[y][x]) continue;

            const N = y > 0 && grid[y-1][x];
            const S = y < ch-1 && grid[y+1][x];
            const E = x < cw-1 && grid[y][x+1];
            const W = x > 0 && grid[y][x-1];
            
            const cardinals = (N?1:0) + (S?1:0) + (E?1:0) + (W?1:0);

            // Rule: Minimum cardinal connections is 2 (prune peninsulas)
            if (cardinals < 2) {
              grid[y][x] = false;
              changed = true;
              continue;
            }

            // Rule: No 1xN bridges (exactly 2 opposite connections)
            if (cardinals === 2) {
              if (N && S) {
                // Vertical bridge: thicken East
                if (x < cw - 1) grid[y][x+1] = true;
                changed = true;
              } else if (E && W) {
                // Horizontal bridge: thicken South
                if (y < ch - 1) grid[y+1][x] = true;
                changed = true;
              }
            }

            // Rule: Prevent double inner corners
            if (cardinals === 4) {
              const NE = grid[y-1][x+1];
              const SE = grid[y+1][x+1];
              const SW = grid[y+1][x-1];
              const NW = grid[y-1][x-1];
              
              const waterDiags = (!NE?1:0) + (!SE?1:0) + (!SW?1:0) + (!NW?1:0);
              if (waterDiags > 1) {
                if (!NE) grid[y-1][x+1] = true;
                else if (!SE) grid[y+1][x+1] = true;
                else if (!SW) grid[y+1][x-1] = true;
                else if (!NW) grid[y-1][x-1] = true;
                changed = true;
              }
            }
          }
        }
      }

      // Auto-Tiling
      const result: MapGridCell[][] = [];
      for (let y = 0; y < ch; y++) {
        const row: MapGridCell[] = [];
        for (let x = 0; x < cw; x++) {
          const isLand = grid[y][x];
          let tileId: string | undefined = undefined;
          
          if (isLand) {
            const N = y > 0 && grid[y-1][x] ? 1 : 0;
            const S = y < ch - 1 && grid[y+1][x] ? 1 : 0;
            const E = x < cw - 1 && grid[y][x+1] ? 1 : 0;
            const W = x > 0 && grid[y][x-1] ? 1 : 0;
            
            let NE = 1, SE = 1, SW = 1, NW = 1;
            if (N && E) NE = grid[y-1][x+1] ? 1 : 0;
            if (S && E) SE = grid[y+1][x+1] ? 1 : 0;
            if (S && W) SW = grid[y+1][x-1] ? 1 : 0;
            if (N && W) NW = grid[y-1][x-1] ? 1 : 0;
            
            tileId = this.getTileId(N, E, S, W, NE, SE, SW, NW) || undefined;
          }
          
          row.push({ x, y, layer: level, isLand, tileId, objects: [] });
        }
        result.push(row);
      }
      results[level] = result;
    }
    
    // 5. Object Scattering Pass
    if (objectAssets && objectAssets.length > 0 && results[1]) {
      const rngScatter = new SeededRandom(seed + 12345);
      const occupancy = new Set<string>();

      const isSlotValid = (gx: number, gy: number, filterCenterOnly: boolean) => {
        const cx = Math.floor(gx / 3);
        const cy = Math.floor(gy / 3);
        if (cy < 0 || cy >= ch || cx < 0 || cx >= cw) return false;
        const cell = results[1][cy][cx];
        if (!cell || !cell.isLand || !cell.tileId) return false;
        if (filterCenterOnly && cell.tileId !== 'CenterFill') return false;
        return !occupancy.has(`${gx},${gy}`);
      };

      for (const asset of objectAssets) {
        if (!asset.amount || asset.amount <= 0) continue;
        const rawBaseTiles = asset.baseTiles && asset.baseTiles.length > 0 ? asset.baseTiles : [{lx: 0, ly: 0}];
        const limit = Math.floor(1.5 * (asset.scale || 1.0));
        let baseTiles = rawBaseTiles.filter((t: {lx: number, ly: number}) => Math.abs(t.lx) <= limit && Math.abs(t.ly) <= limit);
        if (baseTiles.length === 0) baseTiles = [{lx: 0, ly: 0}];
        
        const assetStrVal = Array.from(asset.id).reduce((sum: number, char: any) => sum + char.charCodeAt(0), 0);
        const assetSeed = seed + 12345 + (asset.seedOffset || 0) * 1000 + assetStrVal;
        const assetRng = new SeededRandom(assetSeed);

        const availablePositions: {gx: number, gy: number}[] = [];
        
        for (let gy = 0; gy < ch * 3; gy++) {
          for (let gx = 0; gx < cw * 3; gx++) {
             let canPlace = true;
             for (const tile of baseTiles) {
               const tgx = gx + tile.lx;
               const tgy = gy + tile.ly;
               if (!isSlotValid(tgx, tgy, !asset.allowOnEdge)) {
                 canPlace = false;
                 break;
               }
             }
             if (canPlace) availablePositions.push({gx, gy});
          }
        }

        let placed = 0;
        while (placed < asset.amount && availablePositions.length > 0) {
          const randIdx = Math.floor(assetRng.next() * availablePositions.length);
          const pos = availablePositions[randIdx];
          
          let stillValid = true;
          for (const tile of baseTiles) {
             if (occupancy.has(`${pos.gx + tile.lx},${pos.gy + tile.ly}`)) {
               stillValid = false;
               break;
             }
          }
          
          if (stillValid) {
             const cx = Math.floor(pos.gx / 3);
             const cy = Math.floor(pos.gy / 3);
             const lx = pos.gx - cx * 3 - 1;
             const ly = pos.gy - cy * 3 - 1;
             
             results[1][cy][cx].objects.push({ 
               url: asset.imageUrl, 
               id: asset.id, 
               instanceId: `${asset.id}-${placed}`,
               cellX: cx,
               cellY: cy,
               lx: lx, 
               ly: ly,
               baseTiles: baseTiles
             });

             for (const tile of baseTiles) {
               occupancy.add(`${pos.gx + tile.lx},${pos.gy + tile.ly}`);
             }
             placed++;
          }
          
          availablePositions.splice(randIdx, 1);
        }
      }
    }

    return results;
  }

  public static getTileId(n: number, e: number, s: number, w: number, ne: number, se: number, sw: number, nw: number): string {
    const cCode = `${n}${e}${s}${w}`;
    
    if (cCode === '1111') {
      const dCode = `${ne}${se}${sw}${nw}`;
      if (dCode === '0111') return 'InnerCornerEast';
      if (dCode === '1011') return 'InnerCornerSouth';
      if (dCode === '1101') return 'InnerCornerWest';
      if (dCode === '1110') return 'InnerCornerNorth';
      return 'CenterFill';
    }

    const map: Record<string, string> = {
      '0111': 'EdgeNorthEast',
      '1011': 'EdgeSouthEast',
      '1101': 'EdgeSouthWest',
      '1110': 'EdgeNorthWest',
      '0011': 'OutterCornerEast',
      '1001': 'OutterCornerSouth',
      '1100': 'OutterCornerWest',
      '0110': 'OutterCornerNorth',
    };

    return map[cCode] || 'CenterFill';
  }
}
